from __future__ import annotations

import json
import re
import tempfile
from dataclasses import asdict, dataclass
from pathlib import Path, PurePosixPath
from typing import Iterable


FRONTMATTER_LIMIT = 8_192
NAME_PATTERN = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


@dataclass(frozen=True)
class Scope:
    name: str
    root: Path


@dataclass(frozen=True)
class SkillCandidate:
    name: str
    description: str
    scope: str
    directory: Path
    skill_path: Path


@dataclass(frozen=True)
class CatalogBudget:
    max_entries: int = 50
    max_description_chars: int = 240
    max_catalog_chars: int = 8_000


@dataclass(frozen=True)
class CatalogEntry:
    name: str
    description: str
    scope: str
    directory: str


@dataclass(frozen=True)
class Collision:
    name: str
    winner_scope: str
    shadowed_scopes: tuple[str, ...]


@dataclass(frozen=True)
class Catalog:
    entries: tuple[CatalogEntry, ...]
    collisions: tuple[Collision, ...]
    omitted: tuple[str, ...]
    catalog_chars: int
    report_chars: int

    def model_dict(self) -> dict[str, object]:
        return {"entries": [asdict(entry) for entry in self.entries]}

    def to_dict(self) -> dict[str, object]:
        return {
            "entries": [asdict(entry) for entry in self.entries],
            "collisions": [asdict(collision) for collision in self.collisions],
            "omitted": list(self.omitted),
            "catalog_chars": self.catalog_chars,
            "report_chars": self.report_chars,
        }


class DiscoveryError(ValueError):
    pass


class CollisionError(ValueError):
    pass


class ReferencePathError(ValueError):
    pass


def _frontmatter(path: Path) -> dict[str, str]:
    lines: list[str] = []
    consumed = 0
    with path.open("r", encoding="utf-8") as handle:
        for raw_line in handle:
            consumed += len(raw_line.encode("utf-8"))
            if consumed > FRONTMATTER_LIMIT:
                raise DiscoveryError(f"frontmatter window exceeded for {path}")
            lines.append(raw_line.rstrip("\r\n"))
            if len(lines) > 1 and lines[-1] == "---":
                break
    if not lines or lines[0] != "---" or lines[-1] != "---":
        raise DiscoveryError(f"invalid frontmatter delimiters in {path}")
    end = len(lines) - 1
    fields: dict[str, str] = {}
    index = 1
    while index < end:
        line = lines[index]
        if not line.strip() or line.lstrip().startswith("#"):
            index += 1
            continue
        if line[:1].isspace() or ":" not in line:
            raise DiscoveryError(f"malformed top-level line {index + 1} in {path}")
        key, value = line.split(":", 1)
        key = key.strip()
        if not re.fullmatch(r"[A-Za-z][A-Za-z0-9-]*", key):
            raise DiscoveryError(f"invalid frontmatter field {key!r} in {path}")
        if key in fields:
            raise DiscoveryError(f"duplicate frontmatter field {key!r} in {path}")
        value = value.strip()
        if key == "metadata" and not value:
            nested: dict[str, str] = {}
            index += 1
            while index < end and (not lines[index] or lines[index][:1].isspace()):
                nested_line = lines[index].strip()
                if nested_line:
                    if ":" not in nested_line:
                        raise DiscoveryError(
                            f"malformed metadata line {index + 1} in {path}"
                        )
                    nested_key, nested_value = nested_line.split(":", 1)
                    nested_key = nested_key.strip()
                    if (
                        not re.fullmatch(r"[A-Za-z][A-Za-z0-9-]*", nested_key)
                        or nested_key in nested
                    ):
                        raise DiscoveryError(
                            f"invalid metadata field {nested_key!r} in {path}"
                        )
                    nested[nested_key] = nested_value.strip().strip("\"'")
                index += 1
            fields[key] = json.dumps(nested, sort_keys=True)
            continue
        if value in {">", "|"}:
            block: list[str] = []
            index += 1
            while index < end and (not lines[index] or lines[index][:1].isspace()):
                block.append(lines[index].lstrip())
                index += 1
            fields[key] = (" " if value == ">" else "\n").join(block).strip()
            continue
        fields[key] = value.strip("\"'")
        index += 1
    if not fields.get("name") or not fields.get("description"):
        raise DiscoveryError(f"name and description are required in {path}")
    return fields


def discover_scope(scope: Scope) -> tuple[SkillCandidate, ...]:
    """Read only direct child frontmatter; instruction bodies stay unloaded."""
    if not scope.root.exists():
        return ()
    candidates: list[SkillCandidate] = []
    for directory in sorted(scope.root.iterdir(), key=lambda item: item.name):
        skill_path = directory / "SKILL.md"
        if not directory.is_dir() or directory.is_symlink():
            continue
        if skill_path.is_symlink():
            raise DiscoveryError(f"symlinked SKILL.md is not allowed: {skill_path}")
        if not skill_path.is_file():
            continue
        fields = _frontmatter(skill_path)
        if len(fields["name"]) > 64 or not NAME_PATTERN.fullmatch(fields["name"]):
            raise DiscoveryError(
                f"frontmatter name {fields['name']!r} is not valid portable kebab-case"
            )
        if len(fields["description"]) > 1024:
            raise DiscoveryError(f"description exceeds 1024 characters in {skill_path}")
        if fields["name"] != directory.name:
            raise DiscoveryError(
                f"frontmatter name {fields['name']!r} does not match directory {directory.name!r}"
            )
        candidates.append(
            SkillCandidate(
                name=fields["name"],
                description=fields["description"],
                scope=scope.name,
                directory=directory.resolve(),
                skill_path=skill_path.resolve(),
            )
        )
    return tuple(candidates)


def resolve_collisions(
    candidates: Iterable[SkillCandidate], precedence: tuple[str, ...]
) -> tuple[tuple[SkillCandidate, ...], tuple[Collision, ...]]:
    """Apply a caller-supplied high-to-low scope order."""
    rank = {scope: index for index, scope in enumerate(precedence)}
    grouped: dict[str, list[SkillCandidate]] = {}
    for candidate in candidates:
        if candidate.scope not in rank:
            raise CollisionError(f"scope {candidate.scope!r} is missing from host policy")
        grouped.setdefault(candidate.name, []).append(candidate)

    winners: list[SkillCandidate] = []
    collisions: list[Collision] = []
    for name in sorted(grouped):
        options = sorted(
            grouped[name], key=lambda item: (rank[item.scope], str(item.directory))
        )
        top_rank = rank[options[0].scope]
        tied = [option for option in options if rank[option.scope] == top_rank]
        if len(tied) > 1:
            paths = ", ".join(str(option.directory) for option in tied)
            raise CollisionError(f"ambiguous {name!r} at equal precedence: {paths}")
        winners.append(options[0])
        if len(options) > 1:
            collisions.append(
                Collision(
                    name=name,
                    winner_scope=options[0].scope,
                    shadowed_scopes=tuple(option.scope for option in options[1:]),
                )
            )
    return tuple(winners), tuple(collisions)


def _shorten(text: str, limit: int) -> str:
    if limit < 1:
        return ""
    if len(text) <= limit:
        return text
    if limit == 1:
        return "…"
    return text[: limit - 1].rstrip() + "…"


def build_catalog(
    candidates: Iterable[SkillCandidate],
    precedence: tuple[str, ...],
    budget: CatalogBudget,
) -> Catalog:
    if min(budget.max_entries, budget.max_description_chars, budget.max_catalog_chars) < 1:
        raise ValueError("catalog budgets must be positive")
    winners, collisions = resolve_collisions(candidates, precedence)
    rank = {scope: index for index, scope in enumerate(precedence)}
    ordered = sorted(winners, key=lambda item: (rank[item.scope], item.name))
    entries = [
        CatalogEntry(
            name=candidate.name,
            description=_shorten(candidate.description, budget.max_description_chars),
            scope=candidate.scope,
            directory=str(candidate.directory),
        )
        for candidate in ordered[: budget.max_entries]
    ]
    omitted = [candidate.name for candidate in ordered[budget.max_entries :]]

    def model_size(current_entries: list[CatalogEntry]) -> int:
        payload = {"entries": [asdict(entry) for entry in current_entries]}
        return len(json.dumps(payload, sort_keys=True, separators=(",", ":")))

    used = model_size(entries)
    while used > budget.max_catalog_chars and entries:
        removed = entries.pop()
        omitted.insert(0, removed.name)
        used = model_size(entries)
    if used > budget.max_catalog_chars:
        raise ValueError("model-facing catalog exceeds max_catalog_chars")

    report_chars = 0
    while True:
        report = Catalog(
            tuple(entries), collisions, tuple(omitted), used, report_chars
        )
        measured = len(
            json.dumps(report.to_dict(), sort_keys=True, separators=(",", ":"))
        )
        if measured == report_chars:
            return report
        report_chars = measured


def _candidate_for(entry: CatalogEntry, candidates: Iterable[SkillCandidate]) -> SkillCandidate:
    for candidate in candidates:
        if candidate.name == entry.name and str(candidate.directory) == entry.directory:
            return candidate
    raise KeyError(f"catalog entry {entry.name!r} has no matching candidate")


def load_skill_body(
    entry: CatalogEntry,
    candidates: Iterable[SkillCandidate],
    max_chars: int = 12_000,
) -> str:
    candidate = _candidate_for(entry, candidates)
    text = candidate.skill_path.read_text(encoding="utf-8")
    lines = text.splitlines()
    end = lines.index("---", 1)
    body = "\n".join(lines[end + 1 :]).strip()
    if len(body) > max_chars:
        raise DiscoveryError(f"skill body exceeds {max_chars} characters")
    return body


def validate_reference(skill_directory: Path, reference: str) -> Path:
    """Allow a direct file or one subdirectory, never traversal or deep chains."""
    if not isinstance(reference, str):
        raise ReferencePathError("reference must be a string")
    if "\\" in reference:
        raise ReferencePathError("references must use portable forward slashes")
    relative = PurePosixPath(reference)
    if relative.is_absolute() or any(part in {"", ".", ".."} for part in relative.parts):
        raise ReferencePathError("reference must be a clean relative path")
    if len(relative.parts) > 2:
        raise ReferencePathError("reference may be at most one directory deep")
    root = skill_directory.resolve()
    unresolved = root
    for part in relative.parts:
        unresolved = unresolved / part
        if unresolved.is_symlink():
            raise ReferencePathError("reference path cannot contain symlinks")
    target = unresolved.resolve()
    if target == root or root not in target.parents:
        raise ReferencePathError("reference escapes the skill directory")
    if not target.is_file():
        raise ReferencePathError("reference must resolve to a regular file")
    return target


def load_reference(
    entry: CatalogEntry,
    reference: str,
    max_chars: int = 12_000,
) -> str:
    target = validate_reference(Path(entry.directory), reference)
    content = target.read_text(encoding="utf-8")
    if len(content) > max_chars:
        raise ReferencePathError(f"reference exceeds {max_chars} characters")
    return content


def _write_skill(root: Path, name: str, description: str, body: str) -> None:
    directory = root / name
    (directory / "references").mkdir(parents=True)
    (directory / "SKILL.md").write_text(
        f"---\nname: {name}\ndescription: {description}\n---\n\n{body}\n",
        encoding="utf-8",
    )
    (directory / "references" / "format.md").write_text(
        "# Format\n\nReturn JSON with an evidence array.\n", encoding="utf-8"
    )


def demo() -> None:
    with tempfile.TemporaryDirectory(prefix="lesson-24-") as temp_dir:
        base = Path(temp_dir)
        user_root = base / "user"
        project_root = base / "project"
        _write_skill(
            user_root,
            "evidence-report",
            "Create a general evidence report when findings need citations.",
            "# Evidence report\n\nRead `references/format.md` when formatting the result.",
        )
        _write_skill(
            project_root,
            "evidence-report",
            "Create this project's evidence report when an audit completes.",
            "# Project evidence report\n\nRead `references/format.md` for the schema.",
        )
        _write_skill(
            user_root,
            "meeting-brief",
            "Prepare a meeting brief from supplied notes.",
            "# Meeting brief\n\nSeparate decisions from open questions.",
        )
        candidates = (
            *discover_scope(Scope("project", project_root)),
            *discover_scope(Scope("user", user_root)),
        )
        catalog = build_catalog(
            candidates,
            precedence=("project", "user"),
            budget=CatalogBudget(max_entries=10, max_catalog_chars=2_000),
        )
        selected = next(entry for entry in catalog.entries if entry.name == "evidence-report")
        body = load_skill_body(selected, candidates)
        reference = load_reference(selected, "references/format.md")
        result = {
            "catalog": catalog.to_dict(),
            "disclosure": {
                "level_1_catalog_chars": catalog.catalog_chars,
                "level_2_body_chars": len(body),
                "level_3_reference_chars": len(reference),
            },
        }
    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == "__main__":
    demo()

from __future__ import annotations

import json
import math
import re
from dataclasses import asdict, dataclass, field
from enum import Enum
from typing import Iterable


class Actor(str, Enum):
    HUMAN = "human"
    MODEL = "model"
    AGENT = "agent"
    APPLICATION = "application"
    SKILL = "skill"
    HARNESS = "harness"


def _actor_label(actor: object) -> str:
    value = getattr(actor, "value", actor)
    if isinstance(value, str) and value:
        return value
    if value is None:
        return "unknown"
    return type(value).__name__


@dataclass(frozen=True)
class SkillMetadata:
    name: str
    description: str
    runtime_extensions: dict[str, object] = field(default_factory=dict)


@dataclass(frozen=True)
class InvocationPolicy:
    allow_human: bool = True
    allow_model: bool = True
    allow_agent: bool = True
    allow_programmatic: bool = True
    allow_application: bool = True
    allow_skill: bool = False
    model_threshold: float = 0.2
    harness_allowlist: tuple[str, ...] = ()
    application_allowlist: tuple[str, ...] = ()
    skill_caller_allowlist: tuple[str, ...] = ()
    max_skill_depth: int = 1

    def __post_init__(self) -> None:
        for field_name in (
            "allow_human",
            "allow_model",
            "allow_agent",
            "allow_programmatic",
            "allow_application",
            "allow_skill",
        ):
            if type(getattr(self, field_name)) is not bool:
                raise TypeError(f"{field_name} must be a boolean")
        if (
            isinstance(self.model_threshold, bool)
            or not isinstance(self.model_threshold, (int, float))
            or not math.isfinite(self.model_threshold)
            or not 0.0 <= self.model_threshold <= 1.0
        ):
            raise ValueError("model_threshold must be a finite number from 0 to 1")
        for field_name in (
            "harness_allowlist",
            "application_allowlist",
            "skill_caller_allowlist",
        ):
            value = getattr(self, field_name)
            if not isinstance(value, tuple) or not all(
                isinstance(item, str) and item for item in value
            ):
                raise TypeError(f"{field_name} must be a tuple of non-empty names")
        if type(self.max_skill_depth) is not int or self.max_skill_depth < 1:
            raise ValueError("max_skill_depth must be a positive integer")


@dataclass(frozen=True)
class InvocationRequest:
    actor: Actor
    query: str
    explicit_name: str | None = None
    caller_name: str | None = None
    depth: int = 0


@dataclass(frozen=True)
class InvocationDecision:
    activated: bool
    actor: Actor | str
    skill_name: str | None
    mode: str
    score: float
    reason: str

    def to_dict(self) -> dict[str, object]:
        data = asdict(self)
        data["actor"] = (
            self.actor.value if isinstance(self.actor, Actor) else self.actor
        )
        return data


def _tokens(value: str) -> set[str]:
    return set(re.findall(r"[a-z0-9]+", value.lower()))


def relevance_score(query: str, skill: SkillMetadata) -> float:
    query_tokens = _tokens(query)
    skill_tokens = _tokens(f"{skill.name} {skill.description}")
    if not query_tokens or not skill_tokens:
        return 0.0
    return len(query_tokens & skill_tokens) / len(query_tokens | skill_tokens)


class CorePolicyAdapter:
    """Apply only caller-supplied host policy; ignore extension fields."""

    def __init__(self, policy: InvocationPolicy):
        self.policy = policy

    def allows(
        self,
        skill: SkillMetadata,
        actor: Actor,
        request: InvocationRequest | None = None,
    ) -> tuple[bool, str]:
        if actor is Actor.HUMAN:
            return self.policy.allow_human, "human activation policy"
        if actor is Actor.MODEL:
            return self.policy.allow_model, "model activation policy"
        if actor is Actor.AGENT:
            return self.policy.allow_agent, "agent activation policy"
        if actor is Actor.APPLICATION:
            allowed = (
                self.policy.allow_application
                and skill.name in self.policy.application_allowlist
            )
            return allowed, "application activation policy and target allowlist"
        if actor is Actor.SKILL:
            if not self.policy.allow_skill:
                return False, "skill composition policy"
            if request is None or not request.caller_name:
                return False, "skill composition requires a caller identity"
            if request.caller_name == skill.name:
                return False, "direct skill self-cycle"
            if request.caller_name not in self.policy.skill_caller_allowlist:
                return False, "skill caller allowlist"
            if request.depth < 1 or request.depth > self.policy.max_skill_depth:
                return False, "skill composition depth limit"
            return True, "skill caller allowlist and depth policy"
        if actor is Actor.HARNESS:
            allowed = (
                self.policy.allow_programmatic
                and skill.name in self.policy.harness_allowlist
            )
            return allowed, "programmatic activation policy and allowlist"
        return False, f"unknown actor {_actor_label(actor)!r} has no activation policy"


def _extension_false(value: object) -> bool:
    return value is False or (isinstance(value, str) and value.lower() == "false")


def _extension_true(value: object) -> bool:
    return value is True or (isinstance(value, str) and value.lower() == "true")


class ExtensionPolicyAdapter(CorePolicyAdapter):
    """Example adapter for one host's invocation metadata conventions."""

    def allows(
        self,
        skill: SkillMetadata,
        actor: Actor,
        request: InvocationRequest | None = None,
    ) -> tuple[bool, str]:
        allowed, reason = super().allows(skill, actor, request)
        if not allowed:
            return allowed, reason
        fields = skill.runtime_extensions
        if actor is Actor.HUMAN and _extension_false(fields.get("user-invocable")):
            return False, "host extension user-invocable=false"
        if actor in {Actor.MODEL, Actor.AGENT} and _extension_true(
            fields.get("disable-model-invocation")
        ):
            return False, "host extension disable-model-invocation=true"
        return True, reason


def build_invocation_matrix(
    policy: InvocationPolicy | None = None,
) -> tuple[dict[str, object], ...]:
    active = None if policy is None else (policy.allow_human, policy.allow_model)
    rows = []
    for human, model, meaning in (
        (False, False, "programmatic-only or unavailable"),
        (True, False, "explicit human activation only"),
        (False, True, "implicit model activation only"),
        (True, True, "human and model activation"),
    ):
        rows.append(
            {
                "human": human,
                "model": model,
                "meaning": meaning,
                "active_policy": active == (human, model),
            }
        )
    return tuple(rows)


def route_request(
    skills: Iterable[SkillMetadata],
    request: InvocationRequest,
    adapter: CorePolicyAdapter,
) -> InvocationDecision:
    if not isinstance(request.actor, Actor):
        actor = _actor_label(request.actor)
        return InvocationDecision(
            False,
            actor,
            None,
            "unsupported-actor",
            0.0,
            f"unknown actor {actor!r} has no activation policy",
        )
    candidates = sorted(skills, key=lambda item: item.name)
    explicit_modes = {
        Actor.HUMAN: "explicit-human",
        Actor.APPLICATION: "programmatic-application",
        Actor.SKILL: "composed-skill",
        Actor.HARNESS: "programmatic-harness",
    }
    if request.actor in explicit_modes:
        mode = explicit_modes[request.actor]
        if not request.explicit_name:
            return InvocationDecision(
                False, request.actor, None, mode, 0.0, "an exact skill name is required"
            )
        selected = next(
            (skill for skill in candidates if skill.name == request.explicit_name), None
        )
        if selected is None:
            return InvocationDecision(
                False, request.actor, None, mode, 0.0, "named skill was not discovered"
            )
        allowed, reason = adapter.allows(selected, request.actor, request)
        return InvocationDecision(
            allowed,
            request.actor,
            selected.name,
            mode,
            1.0,
            reason if allowed else f"blocked by {reason}",
        )

    mode = "implicit-model" if request.actor is Actor.MODEL else "implicit-agent"
    if request.explicit_name:
        return InvocationDecision(
            False,
            request.actor,
            None,
            mode,
            0.0,
            "implicit model or agent routing uses task relevance rather than an exact-name channel",
        )
    if not candidates:
        return InvocationDecision(False, request.actor, None, mode, 0.0, "catalog is empty")

    eligible = []
    blocked_reasons = []
    for skill in candidates:
        allowed, reason = adapter.allows(skill, request.actor, request)
        if allowed:
            eligible.append((skill, reason))
        else:
            blocked_reasons.append(reason)
    if not eligible:
        reason = "no discovered skill is eligible for implicit routing"
        if blocked_reasons:
            reason = f"{reason}: {'; '.join(sorted(set(blocked_reasons)))}"
        return InvocationDecision(False, request.actor, None, mode, 0.0, reason)

    scored = [
        (relevance_score(request.query, skill), skill, reason)
        for skill, reason in eligible
    ]
    score, selected, eligibility_reason = max(
        scored, key=lambda item: (item[0], item[1].name)
    )
    if score < adapter.policy.model_threshold:
        return InvocationDecision(
            False,
            request.actor,
            selected.name,
            mode,
            round(score, 4),
            "best match did not meet the host threshold",
        )
    return InvocationDecision(
        True,
        request.actor,
        selected.name,
        mode,
        round(score, 4),
        eligibility_reason,
    )


def demo() -> None:
    skills = (
        SkillMetadata(
            "incident-triage",
            "Triage an incident timeline and separate evidence from hypotheses.",
        ),
        SkillMetadata(
            "release-notes",
            "Draft release notes from merged pull request summaries.",
            {"user-invocable": True, "disable-model-invocation": True},
        ),
        SkillMetadata(
            "release-readiness",
            "Review merged pull request summaries and report release readiness.",
        ),
    )
    policy = InvocationPolicy(
        model_threshold=0.15,
        harness_allowlist=("incident-triage",),
        application_allowlist=("release-notes",),
        allow_skill=True,
        skill_caller_allowlist=("release-readiness",),
        max_skill_depth=2,
    )
    core = CorePolicyAdapter(policy)
    extensions = ExtensionPolicyAdapter(policy)
    requests = (
        InvocationRequest(Actor.HUMAN, "", explicit_name="release-notes"),
        InvocationRequest(Actor.MODEL, "triage this incident timeline evidence"),
        InvocationRequest(Actor.HARNESS, "nightly evaluation", explicit_name="incident-triage"),
        InvocationRequest(Actor.MODEL, "draft release notes from merged pull requests"),
        InvocationRequest(Actor.AGENT, "triage this incident timeline evidence"),
        InvocationRequest(Actor.APPLICATION, "", explicit_name="release-notes"),
        InvocationRequest(
            Actor.SKILL,
            "review incident dependency",
            explicit_name="incident-triage",
            caller_name="release-readiness",
            depth=1,
        ),
    )
    result = {
        "human_model_matrix": build_invocation_matrix(policy),
        "core_decisions": [route_request(skills, request, core).to_dict() for request in requests],
        "extension_adapter_decisions": [
            route_request(skills, request, extensions).to_dict() for request in requests
        ],
    }
    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == "__main__":
    demo()

from __future__ import annotations

import json
import ipaddress
import re
import tempfile
from dataclasses import asdict, dataclass
from enum import Enum
from pathlib import Path
from typing import Iterable
from urllib.parse import urlparse


class Verdict(str, Enum):
    ALLOW = "allow"
    DENY = "deny"
    REQUIRE_APPROVAL = "require-approval"


@dataclass(frozen=True)
class SandboxPolicy:
    workspace_root: Path
    allowed_kinds: tuple[str, ...] = ("read",)
    command_allowlist: tuple[tuple[str, ...], ...] = ()
    network_allowlist: tuple[str, ...] = ()
    approval_kinds: tuple[str, ...] = ("write", "delete", "network")
    permit_secret_use_after_approval: bool = False


@dataclass(frozen=True)
class ActionRequest:
    kind: str
    target: str | None = None
    command: tuple[str, ...] = ()
    url: str | None = None
    payload: str = ""
    influenced_by_untrusted_content: bool = False
    approved: bool = False
    claimed_permissions: tuple[str, ...] = ()


@dataclass(frozen=True)
class ReviewDecision:
    verdict: Verdict
    rule: str
    reason: str
    normalized_target: str | None = None
    normalized_origin: str | None = None
    claimed_permissions_ignored: bool = False
    executed: bool = False

    def to_dict(self) -> dict[str, object]:
        data = asdict(self)
        data["verdict"] = self.verdict.value
        return data


class SandboxViolation(ValueError):
    pass


SECRET_PATTERNS = (
    re.compile(r"(?i)\b(?:api[_-]?key|access[_-]?token|secret|password)\s*[:=]\s*\S+"),
    re.compile(r"(?i)\bauthorization\s*:\s*bearer\s+\S+"),
    re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----"),
)
HOST_LABEL_PATTERN = re.compile(r"^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$")
SHELL_METACHARACTERS = {";", "&&", "||", "|", ">", ">>", "<", "`"}
DESTRUCTIVE_EXECUTABLES = {"rm", "rmdir", "sudo", "chmod", "chown", "mkfs", "dd"}


def contains_secret(value: str) -> bool:
    return any(pattern.search(value) for pattern in SECRET_PATTERNS)


def normalize_https_origin(value: str, *, origin_only: bool = False) -> str:
    """Return a canonical HTTPS origin with an explicit effective port."""
    if not isinstance(value, str) or not value.strip():
        raise ValueError("HTTPS origin must be a non-empty string")
    try:
        parsed = urlparse(value)
    except ValueError as error:
        raise ValueError("HTTPS origin is malformed") from error
    if (
        parsed.scheme.lower() != "https"
        or not parsed.hostname
        or parsed.username
        or parsed.password
    ):
        raise ValueError("URL must use HTTPS, contain a host, and omit userinfo")
    if origin_only and (
        parsed.path not in {"", "/"} or parsed.params or parsed.query or parsed.fragment
    ):
        raise ValueError("allowlist entries must be HTTPS origins without path, query, or fragment")

    hostname = parsed.hostname.rstrip(".").lower()
    if not hostname or "%" in hostname:
        raise ValueError("HTTPS origin contains an invalid host")
    try:
        address = ipaddress.ip_address(hostname)
    except ValueError:
        try:
            hostname = hostname.encode("idna").decode("ascii")
        except UnicodeError as error:
            raise ValueError("HTTPS origin contains an invalid host") from error
        labels = hostname.split(".")
        if len(hostname) > 253 or any(
            not HOST_LABEL_PATTERN.fullmatch(label) for label in labels
        ):
            raise ValueError("HTTPS origin contains an invalid host")
        origin_host = hostname
    else:
        origin_host = address.compressed
        if address.version == 6:
            origin_host = f"[{origin_host}]"
    try:
        port = parsed.port or 443
    except ValueError as error:
        raise ValueError("HTTPS origin contains an invalid port") from error
    return f"https://{origin_host}:{port}"


def normalize_workspace_path(workspace_root: Path, target: str) -> Path:
    root = workspace_root.resolve(strict=True)
    raw_target = Path(target)
    candidate = raw_target if raw_target.is_absolute() else root / raw_target
    resolved = candidate.resolve(strict=False)
    if resolved != root and root not in resolved.parents:
        raise SandboxViolation("path resolves outside the workspace jail")
    if candidate.is_symlink():
        raise SandboxViolation("direct symlink targets are rejected")
    return resolved


def inspect_command(
    command: tuple[str, ...], allowlist: Iterable[tuple[str, ...]]
) -> tuple[bool, str]:
    """Inspect an argv vector without invoking a shell or subprocess."""
    if not command:
        return False, "empty command"
    executable = command[0]
    if Path(executable).name != executable or "/" in executable or "\\" in executable:
        return False, "command must use an allowlisted bare executable name"
    if executable in DESTRUCTIVE_EXECUTABLES:
        return False, f"destructive executable {executable!r} is denied"
    if executable == "git" and len(command) > 1 and command[1] in {"clean", "reset"}:
        return False, f"destructive git subcommand {command[1]!r} is denied"
    if any(token in SHELL_METACHARACTERS for token in command):
        return False, "shell metacharacters are denied; pass a direct argv vector"
    allowed_prefixes = tuple(tuple(prefix) for prefix in allowlist)
    if not any(
        prefix and command[: len(prefix)] == prefix for prefix in allowed_prefixes
    ):
        return False, "command does not match an approved argv prefix"
    return True, "command argv matched an approved prefix in the non-executing review"


def _decision(
    request: ActionRequest,
    verdict: Verdict,
    rule: str,
    reason: str,
    normalized_target: Path | None = None,
    normalized_origin: str | None = None,
) -> ReviewDecision:
    return ReviewDecision(
        verdict=verdict,
        rule=rule,
        reason=reason,
        normalized_target=None if normalized_target is None else str(normalized_target),
        normalized_origin=normalized_origin,
        claimed_permissions_ignored=bool(request.claimed_permissions),
    )


def review_action(policy: SandboxPolicy, request: ActionRequest) -> ReviewDecision:
    """Classify one proposed action. This function has no execution path."""
    if request.kind == "policy-change":
        return _decision(
            request,
            Verdict.DENY,
            "authority-boundary",
            "skill or external content cannot modify the host permission model",
        )
    if request.kind not in policy.allowed_kinds:
        return _decision(
            request,
            Verdict.DENY,
            "kind-allowlist",
            f"action kind {request.kind!r} is not allowed by host policy",
        )

    normalized: Path | None = None
    normalized_origin: str | None = None
    if request.kind in {"read", "write", "delete"}:
        if not request.target:
            return _decision(request, Verdict.DENY, "path-required", "filesystem action needs a target")
        try:
            normalized = normalize_workspace_path(policy.workspace_root, request.target)
        except (OSError, SandboxViolation) as error:
            return _decision(request, Verdict.DENY, "workspace-jail", str(error))

    if request.kind == "command":
        allowed, reason = inspect_command(request.command, policy.command_allowlist)
        if not allowed:
            return _decision(request, Verdict.DENY, "command-review", reason)

    if request.kind == "network":
        if not request.url:
            return _decision(request, Verdict.DENY, "url-required", "network action needs a URL")
        try:
            normalized_origin = normalize_https_origin(request.url)
        except ValueError as error:
            return _decision(
                request,
                Verdict.DENY,
                "network-shape",
                str(error),
            )
        try:
            allowed_origins = {
                normalize_https_origin(origin, origin_only=True)
                for origin in policy.network_allowlist
            }
        except ValueError as error:
            return _decision(
                request,
                Verdict.DENY,
                "network-policy-shape",
                str(error),
                normalized_origin=normalized_origin,
            )
        if normalized_origin not in allowed_origins:
            return _decision(
                request,
                Verdict.DENY,
                "network-allowlist",
                f"HTTPS origin {normalized_origin!r} is not allowlisted",
                normalized_origin=normalized_origin,
            )

    secret_material = contains_secret(request.payload) or contains_secret(
        " ".join(request.command)
    )
    if secret_material and not (
        request.approved and policy.permit_secret_use_after_approval
    ):
        verdict = (
            Verdict.REQUIRE_APPROVAL
            if policy.permit_secret_use_after_approval
            else Verdict.DENY
        )
        return _decision(
            request,
            verdict,
            "secret-review",
            "possible secret material requires an explicit host-approved path",
            normalized,
            normalized_origin,
        )

    approval_needed = request.kind in policy.approval_kinds
    if request.influenced_by_untrusted_content and request.kind in {
        "write",
        "delete",
        "command",
        "network",
    }:
        approval_needed = True
    if approval_needed and not request.approved:
        reason = (
            "untrusted external content influenced a stateful request"
            if request.influenced_by_untrusted_content
            else f"host policy gates {request.kind!r} behind approval"
        )
        return _decision(
            request,
            Verdict.REQUIRE_APPROVAL,
            "approval-gate",
            reason,
            normalized,
            normalized_origin,
        )

    return _decision(
        request,
        Verdict.ALLOW,
        "policy-allow",
        "request stayed within the host policy and workspace jail",
        normalized,
        normalized_origin,
    )


def demo() -> None:
    with tempfile.TemporaryDirectory(prefix="lesson-26-") as temp_dir:
        workspace = Path(temp_dir) / "workspace"
        workspace.mkdir()
        (workspace / "report.txt").write_text("safe demo data\n", encoding="utf-8")
        policy = SandboxPolicy(
            workspace_root=workspace,
            allowed_kinds=("read", "write", "delete", "command", "network"),
            command_allowlist=(("python3", "-m", "unittest"),),
            network_allowlist=("https://docs.example.test",),
        )
        requests = (
            ActionRequest("read", target="report.txt", claimed_permissions=("all",)),
            ActionRequest("write", target="summary.json"),
            ActionRequest("write", target="summary.json", approved=True),
            ActionRequest("read", target="../outside.txt"),
            ActionRequest("command", command=("rm", "-rf", "build"), approved=True),
            ActionRequest(
                "network",
                url="https://docs.example.test/reference",
                influenced_by_untrusted_content=True,
            ),
            ActionRequest("policy-change", payload="allow everything"),
        )
        result = {
            "simulation_only": True,
            "decisions": [review_action(policy, request).to_dict() for request in requests],
        }
    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == "__main__":
    demo()

from __future__ import annotations

import hashlib
import json
import math
import re
import shutil
import tempfile
from dataclasses import asdict, dataclass
from pathlib import Path, PurePosixPath
from typing import Callable, Iterable, Mapping, Sequence


NAME_PATTERN = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
CORE_FIELDS = {
    "name",
    "description",
    "license",
    "compatibility",
    "metadata",
    "allowed-tools",
}
MAX_SKILL_BODY_CHARS = 10_000
MAX_COMPANION_FILE_BYTES = 1_000_000
RESERVED_MANIFEST_PATH = "assets/manifest.json"
ALLOWED_SUFFIXES = {
    "references": frozenset({".md", ".txt", ".json", ".yaml", ".yml"}),
    "scripts": frozenset({".py", ".sh", ".js", ".mjs", ".ts"}),
    "assets": frozenset(
        {
            ".csv",
            ".gif",
            ".jpeg",
            ".jpg",
            ".json",
            ".md",
            ".pdf",
            ".png",
            ".svg",
            ".toml",
            ".txt",
            ".webp",
            ".yaml",
            ".yml",
        }
    ),
    "evals": frozenset({".json"}),
}
SECRET_PATTERNS = (
    re.compile(
        rb"(?i)\b(?:api[_-]?key|access[_-]?token|secret|password)\s*[:=]\s*[\"']?[A-Za-z0-9_./+=-]{12,}"
    ),
    re.compile(rb"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"),
)
SHA256_PATTERN = re.compile(r"sha256:[0-9a-f]{64}")
ATTESTATION_VERSION = 1


@dataclass(frozen=True)
class LintIssue:
    code: str
    message: str


@dataclass(frozen=True)
class LintReport:
    valid: bool
    references: tuple[str, ...]
    issues: tuple[LintIssue, ...]


def _frontmatter_and_body(path: Path) -> tuple[dict[str, str], str]:
    lines = path.read_text(encoding="utf-8").splitlines()
    if not lines or lines[0] != "---" or "---" not in lines[1:]:
        raise ValueError("SKILL.md needs exact frontmatter delimiters")
    end = lines.index("---", 1)
    fields: dict[str, str] = {}
    index = 1
    while index < end:
        line = lines[index]
        if not line.strip() or line.lstrip().startswith("#"):
            index += 1
            continue
        if line[:1].isspace() or ":" not in line:
            raise ValueError(f"malformed top-level line {index + 1}")
        key, value = line.split(":", 1)
        key = key.strip()
        if not re.fullmatch(r"[A-Za-z][A-Za-z0-9-]*", key):
            raise ValueError(f"invalid frontmatter field {key!r}")
        if key in fields:
            raise ValueError(f"duplicate frontmatter field {key!r}")
        value = value.strip()
        if key == "metadata" and not value:
            nested: dict[str, str] = {}
            index += 1
            while index < end and (not lines[index] or lines[index][:1].isspace()):
                nested_line = lines[index].strip()
                if nested_line:
                    if ":" not in nested_line:
                        raise ValueError(f"malformed metadata line {index + 1}")
                    nested_key, nested_value = nested_line.split(":", 1)
                    nested_key = nested_key.strip()
                    if (
                        not re.fullmatch(r"[A-Za-z][A-Za-z0-9-]*", nested_key)
                        or nested_key in nested
                    ):
                        raise ValueError(f"invalid metadata field {nested_key!r}")
                    nested[nested_key] = nested_value.strip().strip("\"'")
                index += 1
            fields[key] = json.dumps(nested, sort_keys=True)
            continue
        if value in {">", "|"}:
            block: list[str] = []
            index += 1
            while index < end and (not lines[index] or lines[index][:1].isspace()):
                block.append(lines[index].lstrip())
                index += 1
            fields[key] = (" " if value == ">" else "\n").join(block).strip()
            continue
        fields[key] = value.strip("\"'")
        index += 1
    return fields, "\n".join(lines[end + 1 :]).strip()


def _bundle_paths(body: str) -> tuple[str, ...]:
    paths: set[str] = set()
    for code_span in re.findall(r"`([^`]+)`", body):
        for raw_token in code_span.split():
            token = raw_token.strip("()[]{}<>,;:'\"").rstrip(".,;:")
            if any(
                marker in token
                for marker in ("references/", "scripts/", "assets/", "evals/")
            ):
                paths.add(token)
    return tuple(sorted(paths))


def _section_has_content(body: str, title: str) -> bool:
    lines = body.splitlines()
    heading = re.compile(rf"^##\s+{re.escape(title)}\s*#*\s*$", re.IGNORECASE)
    for index, line in enumerate(lines):
        if not heading.fullmatch(line):
            continue
        for candidate in lines[index + 1 :]:
            if re.match(r"^#{1,6}\s+", candidate):
                return False
            if candidate.strip():
                return True
        return False
    return False


def _contains_obvious_secret(data: bytes) -> bool:
    return any(pattern.search(data) is not None for pattern in SECRET_PATTERNS)


def lint_package(
    root: Path, allowed_runtime_extensions: Iterable[str] = ()
) -> LintReport:
    issues: list[LintIssue] = []
    skill_path = root / "SKILL.md"
    if not root.is_dir() or root.is_symlink():
        return LintReport(False, (), (LintIssue("bundle-directory", "regular bundle directory required"),))
    if not skill_path.is_file() or skill_path.is_symlink():
        return LintReport(False, (), (LintIssue("skill-file", "regular SKILL.md required"),))
    try:
        fields, body = _frontmatter_and_body(skill_path)
    except ValueError as error:
        return LintReport(False, (), (LintIssue("frontmatter", str(error)),))

    name = fields.get("name", "")
    description = fields.get("description", "")
    if not name or len(name) > 64 or not NAME_PATTERN.fullmatch(name):
        issues.append(LintIssue("name-format", "name must be kebab-case and at most 64 characters"))
    if name != root.name:
        issues.append(LintIssue("name-directory", "frontmatter name must match bundle directory"))
    if not description:
        issues.append(LintIssue("description", "description is required"))
    elif len(description) > 1024:
        issues.append(LintIssue("description-length", "description must be at most 1024 characters"))
    if not body:
        issues.append(LintIssue("body", "instruction body is required"))
    elif len(body) > MAX_SKILL_BODY_CHARS:
        issues.append(
            LintIssue(
                "body-size",
                f"instruction body exceeds {MAX_SKILL_BODY_CHARS} characters",
            )
        )
    if not _section_has_content(body, "Output contract"):
        issues.append(
            LintIssue(
                "output-contract",
                "a non-empty ## Output contract section is required",
            )
        )
    if not _section_has_content(body, "Failure behavior"):
        issues.append(
            LintIssue(
                "failure-behavior",
                "a non-empty ## Failure behavior section is required",
            )
        )

    allowed_extensions = set(allowed_runtime_extensions)
    for field in sorted(set(fields) - CORE_FIELDS):
        if field not in allowed_extensions:
            issues.append(
                LintIssue(
                    "runtime-extension",
                    f"runtime field {field!r} is not explicitly allowed",
                )
            )

    references = _bundle_paths(body)
    for reference in references:
        if "\\" in reference:
            issues.append(LintIssue("reference-shape", f"invalid direct reference {reference!r}"))
            continue
        relative = PurePosixPath(reference)
        if (
            relative.is_absolute()
            or any(part in {"", ".", ".."} for part in relative.parts)
            or len(relative.parts) != 2
            or relative.parts[0] not in {"references", "scripts", "assets", "evals"}
        ):
            issues.append(LintIssue("reference-shape", f"invalid direct reference {reference!r}"))
            continue
        parent = root / relative.parts[0]
        target = parent / relative.parts[1]
        if parent.is_symlink() or not target.is_file() or target.is_symlink():
            issues.append(LintIssue("reference-missing", f"missing regular file {reference!r}"))

    packaged_files: set[str] = set()
    for path in root.rglob("*"):
        if path.is_symlink():
            issues.append(LintIssue("symlink", f"symlink is not portable: {path.relative_to(root)}"))
        elif path == skill_path:
            continue
        elif path.is_file():
            relative = path.relative_to(root).as_posix()
            packaged_files.add(relative)
            if len(path.relative_to(root).parts) != 2:
                issues.append(LintIssue("package-depth", f"file is not one level deep: {relative}"))
                continue
            directory = path.relative_to(root).parts[0]
            allowed_suffixes = ALLOWED_SUFFIXES.get(directory)
            if allowed_suffixes is None or path.suffix.lower() not in allowed_suffixes:
                issues.append(
                    LintIssue(
                        "file-type",
                        f"unsupported {directory} file type: {relative}",
                    )
                )
            if path.stat().st_size > MAX_COMPANION_FILE_BYTES:
                issues.append(
                    LintIssue(
                        "file-size",
                        f"companion file exceeds {MAX_COMPANION_FILE_BYTES} bytes: {relative}",
                    )
                )
            if _contains_obvious_secret(path.read_bytes()):
                issues.append(
                    LintIssue(
                        "secret-material",
                        f"possible secret material in {relative}",
                    )
                )
        elif not path.is_dir():
            issues.append(
                LintIssue(
                    "special-file",
                    f"special file is not portable: {path.relative_to(root)}",
                )
            )
    if _contains_obvious_secret(skill_path.read_bytes()):
        issues.append(LintIssue("secret-material", "possible secret material in SKILL.md"))
    for orphan in sorted(packaged_files - set(references)):
        issues.append(LintIssue("orphan-file", f"SKILL.md does not directly reference {orphan!r}"))
    return LintReport(not issues, references, tuple(issues))


@dataclass(frozen=True)
class TriggerCase:
    case_id: str
    prompt: str
    expected: bool


@dataclass(frozen=True)
class KeywordRouter:
    terms: tuple[str, ...]
    threshold: int = 2

    def __call__(self, prompt: str, run_index: int = 0) -> bool:
        del run_index
        prompt_terms = set(re.findall(r"[a-z0-9]+", prompt.lower()))
        return len(prompt_terms & set(self.terms)) >= self.threshold


def _validate_trigger_cases(cases: Sequence[TriggerCase]) -> None:
    seen: set[str] = set()
    for case in cases:
        if (
            not isinstance(case.case_id, str)
            or not case.case_id.strip()
            or case.case_id != case.case_id.strip()
            or case.case_id in seen
        ):
            raise ValueError("trigger case ids must be unique and non-empty")
        if (
            not isinstance(case.prompt, str)
            or not case.prompt.strip()
            or case.prompt != case.prompt.strip()
        ):
            raise ValueError(
                "trigger prompts must be non-empty and have no surrounding whitespace"
            )
        seen.add(case.case_id)


def classification_metrics(
    expected: Sequence[bool], predicted: Sequence[bool]
) -> dict[str, float | int]:
    if len(expected) != len(predicted):
        raise ValueError("expected and predicted lengths must match")
    tp = sum(want and got for want, got in zip(expected, predicted))
    fp = sum(not want and got for want, got in zip(expected, predicted))
    tn = sum(not want and not got for want, got in zip(expected, predicted))
    fn = sum(want and not got for want, got in zip(expected, predicted))
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    accuracy = (tp + tn) / len(expected) if expected else 0.0
    return {
        "true_positive": tp,
        "false_positive": fp,
        "true_negative": tn,
        "false_negative": fn,
        "precision": round(precision, 4),
        "recall": round(recall, 4),
        "accuracy": round(accuracy, 4),
    }


def evaluate_triggers(
    cases: Sequence[TriggerCase], router: Callable[[str, int], bool]
) -> dict[str, object]:
    observations = repeated_run_observations(cases, router, 1)
    return trigger_report_from_observations(cases, observations)


def trigger_report_from_observations(
    cases: Sequence[TriggerCase], observations: Mapping[str, Sequence[bool]]
) -> dict[str, object]:
    _validate_trigger_cases(cases)
    if set(observations) != {case.case_id for case in cases} or any(
        not observations[case.case_id]
        or any(type(value) is not bool for value in observations[case.case_id])
        for case in cases
    ):
        raise ValueError("every trigger case needs at least one boolean observation")
    expected = [
        case.expected
        for case in cases
        for _ in observations[case.case_id]
    ]
    predicted = [
        value
        for case in cases
        for value in observations[case.case_id]
    ]
    metrics = classification_metrics(expected, predicted)
    return {
        "metrics": metrics,
        "cases": [
            {
                "id": case.case_id,
                "expected": case.expected,
                "predicted": observations[case.case_id][0],
                "observed_predictions": list(observations[case.case_id]),
                "passed": all(
                    case.expected == prediction
                    for prediction in observations[case.case_id]
                ),
            }
            for case in cases
        ],
    }


def repeated_run_observations(
    cases: Sequence[TriggerCase],
    router: Callable[[str, int], bool],
    runs: int,
) -> dict[str, tuple[bool, ...]]:
    if runs < 1:
        raise ValueError("runs must be positive")
    _validate_trigger_cases(cases)
    return {
        case.case_id: tuple(bool(router(case.prompt, run)) for run in range(runs))
        for case in cases
    }


def rates_from_observations(
    cases: Sequence[TriggerCase], observations: Mapping[str, Sequence[bool]]
) -> dict[str, float]:
    _validate_trigger_cases(cases)
    if set(observations) != {case.case_id for case in cases} or any(
        not observations[case.case_id]
        or any(type(value) is not bool for value in observations[case.case_id])
        for case in cases
    ):
        raise ValueError("every trigger case needs at least one boolean observation")
    return {
        case.case_id: round(
            sum(value == case.expected for value in observations[case.case_id])
            / len(observations[case.case_id]),
            4,
        )
        for case in cases
    }


def repeated_run_rates(
    cases: Sequence[TriggerCase],
    router: Callable[[str, int], bool],
    runs: int,
) -> dict[str, float]:
    observations = repeated_run_observations(cases, router, runs)
    return rates_from_observations(cases, observations)


@dataclass(frozen=True)
class ArtifactContract:
    required_headings: tuple[str, ...] = ()
    required_terms: tuple[str, ...] = ()
    forbidden_terms: tuple[str, ...] = ()


def evaluate_artifact(text: str, contract: ArtifactContract) -> dict[str, object]:
    def has_heading(heading: str) -> bool:
        pattern = rf"^#{{1,6}}\s+{re.escape(heading)}\s*#*\s*$"
        return re.search(pattern, text, re.MULTILINE) is not None

    def has_term(term: str) -> bool:
        pattern = rf"(?<!\w){re.escape(term)}(?!\w)"
        return re.search(pattern, text, re.IGNORECASE) is not None

    missing_headings = [
        heading
        for heading in contract.required_headings
        if not has_heading(heading)
    ]
    missing_terms = [term for term in contract.required_terms if not has_term(term)]
    forbidden_hits = [term for term in contract.forbidden_terms if has_term(term)]
    passed = not missing_headings and not missing_terms and not forbidden_hits
    return {
        "passed": passed,
        "missing_headings": missing_headings,
        "missing_terms": missing_terms,
        "forbidden_hits": forbidden_hits,
    }


def compare_artifacts(
    baseline: str, with_skill: str, contract: ArtifactContract
) -> dict[str, object]:
    baseline_result = evaluate_artifact(baseline, contract)
    skill_result = evaluate_artifact(with_skill, contract)
    return {
        "baseline": baseline_result,
        "with_skill": skill_result,
        "skill_improves_pass_state": not baseline_result["passed"] and skill_result["passed"],
    }


@dataclass(frozen=True)
class EvidenceCheck:
    check_id: str
    passed: bool
    evidence: str


def evaluate_evidence_checks(
    cases: Sequence[EvidenceCheck], layer: str
) -> dict[str, object]:
    if not cases:
        raise ValueError(f"{layer} requires at least one explicit check")
    seen: set[str] = set()
    normalized: list[dict[str, object]] = []
    for case in cases:
        if (
            not isinstance(case.check_id, str)
            or not case.check_id.strip()
            or case.check_id != case.check_id.strip()
            or case.check_id in seen
        ):
            raise ValueError(
                f"{layer} check ids must be unique non-empty strings without surrounding whitespace"
            )
        if type(case.passed) is not bool:
            raise ValueError(f"{layer} check {case.check_id!r} needs a boolean verdict")
        if not isinstance(case.evidence, str) or not case.evidence.strip():
            raise ValueError(f"{layer} check {case.check_id!r} needs evidence")
        seen.add(case.check_id)
        normalized.append(asdict(case))
    return {"passed": all(case.passed for case in cases), "cases": normalized}


def build_manifest(root: Path) -> dict[str, str]:
    if not root.is_dir() or root.is_symlink():
        raise ValueError("manifest root must be a regular directory")
    manifest: dict[str, str] = {}
    for path in sorted(root.rglob("*"), key=lambda item: item.as_posix()):
        relative = path.relative_to(root).as_posix()
        if path.is_symlink():
            raise ValueError(f"manifest tree contains a symlink: {relative}")
        if relative == RESERVED_MANIFEST_PATH:
            if not path.is_file():
                raise ValueError("reserved manifest path must be a regular file")
            continue
        if path.is_file():
            digest = hashlib.sha256(path.read_bytes()).hexdigest()
            manifest[relative] = f"sha256:{digest}"
        elif not path.is_dir():
            raise ValueError(f"manifest tree contains a special file: {relative}")
    if not manifest:
        raise ValueError("manifest cannot describe an empty directory")
    return manifest


def verify_manifest(root: Path, expected: Mapping[str, str]) -> dict[str, object]:
    issues: list[str] = []
    normalized: dict[str, str] = {}
    for raw_path, digest in expected.items():
        if not isinstance(raw_path, str) or not isinstance(digest, str):
            issues.append("manifest paths and digests must be strings")
            continue
        relative = PurePosixPath(raw_path)
        if (
            "\\" in raw_path
            or relative.is_absolute()
            or any(part in {"", ".", ".."} for part in relative.parts)
            or raw_path != relative.as_posix()
        ):
            issues.append(f"invalid manifest path: {raw_path!r}")
            continue
        if relative.as_posix() == RESERVED_MANIFEST_PATH:
            issues.append(
                f"reserved manifest path must not be listed: {raw_path!r}"
            )
            continue
        if not SHA256_PATTERN.fullmatch(digest):
            issues.append(f"invalid manifest digest: {raw_path!r}")
            continue
        normalized[relative.as_posix()] = digest
    try:
        actual = build_manifest(root)
    except ValueError as error:
        issues.append(str(error))
        actual = {}
    missing = sorted(set(normalized) - set(actual))
    unexpected = sorted(set(actual) - set(normalized))
    mismatched = sorted(
        path
        for path in set(normalized) & set(actual)
        if normalized[path] != actual[path]
    )
    return {
        "passed": not issues and not missing and not unexpected and not mismatched,
        "issues": issues,
        "missing": missing,
        "unexpected": unexpected,
        "mismatched": mismatched,
    }


@dataclass(frozen=True)
class PackageRequirements:
    companion_files: bool = False
    script_execution: bool = False
    runtime_extensions: tuple[str, ...] = ()


@dataclass(frozen=True)
class HostCapabilities:
    name: str
    loads_core_skill: bool
    preserves_companion_files: bool
    runs_bundled_scripts: bool
    supported_extensions: tuple[str, ...] = ()


def portability_matrix(
    requirements: PackageRequirements,
    hosts: Iterable[HostCapabilities],
) -> tuple[dict[str, object], ...]:
    rows: list[dict[str, object]] = []
    seen_hosts: set[str] = set()
    for host in hosts:
        if (
            not isinstance(host.name, str)
            or not host.name.strip()
            or host.name != host.name.strip()
            or host.name in seen_hosts
        ):
            raise ValueError("host names must be unique and non-empty")
        seen_hosts.add(host.name)
        missing: list[str] = []
        if not host.loads_core_skill:
            status = "unsupported"
            missing.append("core-skill-loader")
        else:
            if requirements.companion_files and not host.preserves_companion_files:
                missing.append("companion-files")
            if requirements.script_execution and not host.runs_bundled_scripts:
                missing.append("script-execution")
            unsupported_extensions = sorted(
                set(requirements.runtime_extensions) - set(host.supported_extensions)
            )
            missing.extend(f"extension:{field}" for field in unsupported_extensions)
            status = "native" if not missing else "adapter-required"
        rows.append({"host": host.name, "status": status, "missing": missing})
    return tuple(rows)


@dataclass(frozen=True)
class ReleaseThresholds:
    min_precision: float = 0.8
    min_recall: float = 0.8
    min_repeat_rate: float = 0.9
    min_native_hosts: int = 1

    def __post_init__(self) -> None:
        for field_name in ("min_precision", "min_recall", "min_repeat_rate"):
            value = getattr(self, field_name)
            if (
                isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(value)
                or not 0.0 <= value <= 1.0
            ):
                raise ValueError(f"{field_name} must be a finite number from 0 to 1")
        if type(self.min_native_hosts) is not int or self.min_native_hosts < 1:
            raise ValueError("min_native_hosts must be a positive integer")


@dataclass(frozen=True)
class EvaluationProvenance:
    trigger_mode: str = "deterministic-fixture"
    artifact_mode: str = "fixture"
    evidence_mode: str = "deterministic-fixture"
    host_mode: str = "deterministic-fixture"
    artifact_source: str = ""
    evidence_source: str = ""
    host_source: str = ""
    trigger_source: str = ""
    baseline_digest: str = ""
    with_skill_digest: str = ""
    checks_digest: str = ""
    host_digest: str = ""
    trigger_digest: str = ""


def artifact_digest(value: str) -> str:
    return f"sha256:{hashlib.sha256(value.encode('utf-8')).hexdigest()}"


def bytes_digest(value: bytes) -> str:
    return f"sha256:{hashlib.sha256(value).hexdigest()}"


def _canonical_digest(value: object) -> str:
    encoded = json.dumps(
        value, ensure_ascii=False, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    return bytes_digest(encoded)


def evidence_digest(
    script_checks: Sequence[EvidenceCheck], safety_checks: Sequence[EvidenceCheck]
) -> str:
    payload = {
        "script_checks": [asdict(check) for check in script_checks],
        "safety_checks": [asdict(check) for check in safety_checks],
    }
    return _canonical_digest(payload)


def host_matrix_digest(
    requirements: PackageRequirements, hosts: Sequence[HostCapabilities]
) -> str:
    payload = {
        "requirements": asdict(requirements),
        "hosts": [asdict(host) for host in hosts],
    }
    return _canonical_digest(payload)


def trigger_results_digest(
    cases: Sequence[TriggerCase],
    observations: Mapping[str, Sequence[bool]],
) -> str:
    trigger_report_from_observations(cases, observations)
    payload = {
        "cases": [asdict(case) for case in cases],
        "observations": {
            case.case_id: list(observations[case.case_id]) for case in cases
        },
    }
    return _canonical_digest(payload)


def local_evidence_root(
    cases: Sequence[TriggerCase],
    observations: Mapping[str, Sequence[bool]],
    baseline_artifact: str,
    with_skill_artifact: str,
    artifact_contract: ArtifactContract,
    script_checks: Sequence[EvidenceCheck],
    safety_checks: Sequence[EvidenceCheck],
    requirements: PackageRequirements,
    hosts: Sequence[HostCapabilities],
    manifest: Mapping[str, str],
    thresholds: ReleaseThresholds,
    provenance: EvaluationProvenance,
) -> str:
    trigger_report_from_observations(cases, observations)
    payload = {
        "triggers": {
            "cases": [asdict(case) for case in cases],
            "observations": {
                case.case_id: list(observations[case.case_id]) for case in cases
            },
        },
        "artifacts": {
            "baseline": baseline_artifact,
            "withSkill": with_skill_artifact,
            "contract": asdict(artifact_contract),
        },
        "evidence": {
            "scriptChecks": [asdict(check) for check in script_checks],
            "safetyChecks": [asdict(check) for check in safety_checks],
        },
        "portability": {
            "requirements": asdict(requirements),
            "minimumNativeHosts": thresholds.min_native_hosts,
            "hosts": [asdict(host) for host in hosts],
        },
        "manifest": dict(manifest),
        "thresholds": asdict(thresholds),
        "provenance": asdict(provenance),
    }
    return _canonical_digest(payload)


def build_external_attestation(evidence_root: str) -> bytes:
    if not SHA256_PATTERN.fullmatch(evidence_root):
        raise ValueError("evidence root must be a SHA-256 digest")
    return json.dumps(
        {
            "attestationVersion": ATTESTATION_VERSION,
            "evidenceRoot": evidence_root,
        },
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")


def verify_external_attestation(
    evidence_root: str,
    attestation_payload: bytes | None,
    trusted_attestation_digest: str | None,
) -> dict[str, object]:
    issues: list[str] = []
    if attestation_payload is None:
        issues.append("trusted external attestation was not supplied")
    if trusted_attestation_digest is None:
        issues.append("trusted attestation SHA-256 was not supplied out of band")
    if issues:
        return {"valid": False, "issues": issues, "attestation_digest": None}
    if not isinstance(attestation_payload, bytes):
        return {
            "valid": False,
            "issues": ["external attestation payload must be bytes"],
            "attestation_digest": None,
        }
    assert trusted_attestation_digest is not None
    actual_digest = bytes_digest(attestation_payload)
    if not SHA256_PATTERN.fullmatch(trusted_attestation_digest):
        issues.append("trusted attestation SHA-256 has an invalid format")
    elif actual_digest != trusted_attestation_digest:
        issues.append("external attestation does not match the trusted SHA-256")
    try:
        decoded = json.loads(attestation_payload.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        issues.append("external attestation must be a UTF-8 JSON object")
        decoded = None
    if decoded is not None:
        if not isinstance(decoded, dict):
            issues.append("external attestation root must be an object")
        else:
            if (
                type(decoded.get("attestationVersion")) is not int
                or decoded.get("attestationVersion") != ATTESTATION_VERSION
            ):
                issues.append("attestationVersion must be the supported integer value 1")
            if decoded.get("evidenceRoot") != evidence_root:
                issues.append("external attestation evidenceRoot does not match")
    return {
        "valid": not issues,
        "issues": issues,
        "attestation_digest": actual_digest,
    }


def evaluate_provenance(
    provenance: EvaluationProvenance,
    baseline_artifact: str,
    with_skill_artifact: str,
    script_checks: Sequence[EvidenceCheck],
    safety_checks: Sequence[EvidenceCheck],
    requirements: PackageRequirements,
    hosts: Sequence[HostCapabilities],
    cases: Sequence[TriggerCase],
    observations: Mapping[str, Sequence[bool]],
) -> dict[str, object]:
    if provenance.trigger_mode not in {
        "deterministic-fixture",
        "captured-observations",
    }:
        raise ValueError("unsupported trigger provenance mode")
    if provenance.artifact_mode not in {"fixture", "captured-artifacts"}:
        raise ValueError("unsupported artifact provenance mode")
    if provenance.evidence_mode not in {
        "deterministic-fixture",
        "captured-results",
    }:
        raise ValueError("unsupported evidence provenance mode")
    if provenance.host_mode not in {
        "deterministic-fixture",
        "captured-capabilities",
    }:
        raise ValueError("unsupported host provenance mode")

    issues: list[str] = []
    trigger_integrity = False
    if provenance.trigger_mode == "captured-observations":
        trigger_issue_count = len(issues)
        if not provenance.trigger_source.strip():
            issues.append("captured trigger observations need a non-empty source")
        if provenance.trigger_digest != trigger_results_digest(cases, observations):
            issues.append("trigger observation digest does not match")
        trigger_integrity = len(issues) == trigger_issue_count

    artifact_issue_count = len(issues)
    artifact_integrity = False
    if provenance.artifact_mode == "captured-artifacts":
        if not provenance.artifact_source.strip():
            issues.append("captured artifacts need a non-empty source")
        if provenance.baseline_digest != artifact_digest(baseline_artifact):
            issues.append("artifact baseline digest does not match")
        if provenance.with_skill_digest != artifact_digest(with_skill_artifact):
            issues.append("with-skill artifact digest does not match")
        artifact_integrity = len(issues) == artifact_issue_count

    evidence_issue_count = len(issues)
    evidence_integrity = False
    if provenance.evidence_mode == "captured-results":
        if not provenance.evidence_source.strip():
            issues.append("captured evidence needs a non-empty source")
        if provenance.checks_digest != evidence_digest(script_checks, safety_checks):
            issues.append("evidence checks digest does not match")
        evidence_integrity = len(issues) == evidence_issue_count
    host_issue_count = len(issues)
    host_integrity = False
    if provenance.host_mode == "captured-capabilities":
        if not provenance.host_source.strip():
            issues.append("captured host capabilities need a non-empty source")
        if provenance.host_digest != host_matrix_digest(requirements, hosts):
            issues.append("host capability matrix digest does not match")
        host_integrity = len(issues) == host_issue_count
    return {
        "triggerMode": provenance.trigger_mode,
        "artifactMode": provenance.artifact_mode,
        "evidenceMode": provenance.evidence_mode,
        "hostMode": provenance.host_mode,
        "triggerIntegrity": trigger_integrity,
        "artifactIntegrity": artifact_integrity,
        "evidenceIntegrity": evidence_integrity,
        "hostIntegrity": host_integrity,
        "issues": issues,
    }


def run_release_gate(
    package_root: Path,
    cases: Sequence[TriggerCase],
    router: Callable[[str, int], bool],
    runs: int,
    baseline_artifact: str,
    with_skill_artifact: str,
    artifact_contract: ArtifactContract,
    requirements: PackageRequirements,
    hosts: Iterable[HostCapabilities],
    script_checks: Sequence[EvidenceCheck],
    safety_checks: Sequence[EvidenceCheck],
    installed_root: Path,
    manifest: Mapping[str, str],
    provenance: EvaluationProvenance = EvaluationProvenance(),
    thresholds: ReleaseThresholds = ReleaseThresholds(),
    attestation_payload: bytes | None = None,
    trusted_attestation_digest: str | None = None,
) -> dict[str, object]:
    _validate_trigger_cases(cases)
    if not cases or not any(case.expected for case in cases) or not any(
        not case.expected for case in cases
    ):
        raise ValueError("release gate requires positive and near-miss negative trigger cases")
    lint = lint_package(package_root, requirements.runtime_extensions)
    observations = repeated_run_observations(cases, router, runs)
    triggers = trigger_report_from_observations(cases, observations)
    rates = rates_from_observations(cases, observations)
    artifacts = compare_artifacts(baseline_artifact, with_skill_artifact, artifact_contract)
    host_list = tuple(hosts)
    if not host_list:
        raise ValueError("release gate requires at least one host capability record")
    portability = portability_matrix(requirements, host_list)
    scripts = evaluate_evidence_checks(script_checks, "script correctness")
    safety = evaluate_evidence_checks(safety_checks, "safety")
    source_manifest = verify_manifest(package_root, manifest)
    installed_manifest = verify_manifest(installed_root, manifest)
    provenance_report = evaluate_provenance(
        provenance,
        baseline_artifact,
        with_skill_artifact,
        script_checks,
        safety_checks,
        requirements,
        host_list,
        cases,
        observations,
    )
    if package_root.resolve() == installed_root.resolve():
        installed_manifest = {
            **installed_manifest,
            "passed": False,
            "issues": [
                *installed_manifest["issues"],
                "installed tree must be distinct from the source bundle",
            ],
        }
    metrics = triggers["metrics"]
    assert isinstance(metrics, dict)
    native_hosts = sum(row["status"] == "native" for row in portability)
    checks = {
        "structure": lint.valid,
        "precision": float(metrics["precision"]) >= thresholds.min_precision,
        "recall": float(metrics["recall"]) >= thresholds.min_recall,
        "repeated_runs": min(rates.values(), default=0.0) >= thresholds.min_repeat_rate,
        "with_skill_artifact": bool(artifacts["with_skill"]["passed"]),
        "artifact_improvement": bool(artifacts["skill_improves_pass_state"]),
        "script_correctness": bool(scripts["passed"]),
        "safety": bool(safety["passed"]),
        "source_manifest": bool(source_manifest["passed"]),
        "installed_tree": bool(installed_manifest["passed"]),
        "native_hosts": native_hosts >= thresholds.min_native_hosts,
    }
    checks_passed = all(checks.values())
    fixture_passed = checks_passed and (
        provenance_report["triggerMode"] == "deterministic-fixture"
        and provenance_report["artifactMode"] == "fixture"
        and provenance_report["evidenceMode"] == "deterministic-fixture"
        and provenance_report["hostMode"] == "deterministic-fixture"
    )
    local_evidence_ready = (
        bool(provenance_report["triggerIntegrity"])
        and bool(provenance_report["artifactIntegrity"])
        and bool(provenance_report["evidenceIntegrity"])
        and bool(provenance_report["hostIntegrity"])
    )
    evidence_root = local_evidence_root(
        cases,
        observations,
        baseline_artifact,
        with_skill_artifact,
        artifact_contract,
        script_checks,
        safety_checks,
        requirements,
        host_list,
        manifest,
        thresholds,
        provenance,
    )
    trust_anchor = verify_external_attestation(
        evidence_root, attestation_payload, trusted_attestation_digest
    )
    trust_anchor_valid = bool(trust_anchor["valid"])
    production_ready = (
        checks_passed and local_evidence_ready and trust_anchor_valid
    )
    return {
        "passed": production_ready,
        "checks_passed": checks_passed,
        "fixture_passed": fixture_passed,
        "local_evidence_ready": local_evidence_ready,
        "trust_anchor_valid": trust_anchor_valid,
        "production_ready": production_ready,
        "evidence_root": evidence_root,
        "trust_anchor": trust_anchor,
        "checks": checks,
        "provenance": provenance_report,
        "lint": {
            "valid": lint.valid,
            "references": list(lint.references),
            "issues": [asdict(issue) for issue in lint.issues],
        },
        "triggers": triggers,
        "trigger_observations": {
            case.case_id: list(observations[case.case_id]) for case in cases
        },
        "repeated_run_rates": rates,
        "artifacts": artifacts,
        "scripts": scripts,
        "safety": safety,
        "packaging": {
            "source_manifest": source_manifest,
            "installed_tree": installed_manifest,
        },
        "portability": list(portability),
    }


def demo() -> None:
    package_root = Path(__file__).resolve().parents[1] / "outputs" / "skill-release-gate"
    cases = (
        TriggerCase("positive-package", "evaluate this skill package before release", True),
        TriggerCase("positive-trigger", "measure skill trigger precision and recall", True),
        TriggerCase("positive-portability", "check bundle portability across hosts", True),
