"""Phase 13 Lesson 28: MCP tool contracts and content.
Lesson: ../docs/en.md
Specification: https://modelcontextprotocol.io/specification/2026-07-28/server/tools
Utilities: completion and pagination in the MCP 2026-07-28 specification.
This example uses only Python's standard library.
"""

from __future__ import annotations

import base64
import json
import re
from dataclasses import dataclass
from typing import Any


PROTOCOL_VERSION = "2026-07-28"
PROTOCOL_META = "io.modelcontextprotocol/protocolVersion"
CAPABILITIES_META = "io.modelcontextprotocol/clientCapabilities"
CLIENT_INFO_META = "io.modelcontextprotocol/clientInfo"
SERVER_INFO_META = "io.modelcontextprotocol/serverInfo"
HEADER_TOKEN = re.compile(r"[!#$%&'*+\-.^_`|~0-9A-Za-z]+")
BASE64_SENTINEL_PREFIX = "=?base64?"
BASE64_SENTINEL_SUFFIX = "?="
JS_SAFE_INTEGER_MIN = -(2**53) + 1
JS_SAFE_INTEGER_MAX = 2**53 - 1
MAX_TOOL_LIST_PAGES = 100
SENSITIVE_NAMES = {
    "api_key",
    "apikey",
    "authorization",
    "password",
    "secret",
    "token",
}


class ContractViolation(ValueError):
    """Raised when a descriptor or result violates the enforced contract."""


@dataclass
class McpError(Exception):
    code: int
    message: str
    data: dict[str, Any] | None = None


def request_meta() -> dict[str, Any]:
    return {
        PROTOCOL_META: PROTOCOL_VERSION,
        CAPABILITIES_META: {"completions": {}},
        CLIENT_INFO_META: {"name": "contract-client", "version": "1.0.0"},
    }


def server_meta() -> dict[str, Any]:
    return {SERVER_INFO_META: {"name": "contract-lab", "version": "1.0.0"}}


def complete(**fields: Any) -> dict[str, Any]:
    return {"resultType": "complete", **fields, "_meta": server_meta()}


def validate_request_meta(params: dict[str, Any]) -> None:
    meta = params.get("_meta")
    if not isinstance(meta, dict):
        raise McpError(-32602, "missing request _meta")
    version = meta.get(PROTOCOL_META)
    if not isinstance(version, str):
        raise McpError(-32602, "missing protocol version")
    if version != PROTOCOL_VERSION:
        raise McpError(
            -32022,
            "unsupported protocol version",
            {"supported": [PROTOCOL_VERSION], "requested": version},
        )
    if not isinstance(meta.get(CAPABILITIES_META), dict):
        raise McpError(-32602, "missing client capabilities")


def _matches_type(value: Any, expected: str) -> bool:
    if expected == "null":
        return value is None
    if expected == "boolean":
        return isinstance(value, bool)
    if expected == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if expected == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if expected == "string":
        return isinstance(value, str)
    if expected == "array":
        return isinstance(value, list)
    if expected == "object":
        return isinstance(value, dict)
    raise ContractViolation(f"unsupported schema type at validation boundary: {expected}")


def validate_json_schema(value: Any, schema: dict[str, Any], path: str = "$") -> None:
    """Validate the small JSON Schema 2020-12 subset used by this lesson."""

    if not isinstance(schema, dict):
        raise ContractViolation(f"{path}: schema must be an object")
    if "enum" in schema and value not in schema["enum"]:
        raise ContractViolation(f"{path}: value is not in enum")

    expected = schema.get("type")
    if expected is not None:
        if not isinstance(expected, str) or not _matches_type(value, expected):
            raise ContractViolation(f"{path}: expected {expected}")

    if isinstance(value, dict):
        properties = schema.get("properties", {})
        required = schema.get("required", [])
        if not isinstance(properties, dict) or not isinstance(required, list):
            raise ContractViolation(f"{path}: malformed object schema")
        for name in required:
            if name not in value:
                raise ContractViolation(f"{path}.{name}: required property missing")
        for name, item in value.items():
            if name in properties:
                validate_json_schema(item, properties[name], f"{path}.{name}")
            elif schema.get("additionalProperties") is False:
                raise ContractViolation(f"{path}.{name}: additional property rejected")

    if isinstance(value, list) and "items" in schema:
        for index, item in enumerate(value):
            validate_json_schema(item, schema["items"], f"{path}[{index}]")

    if isinstance(value, str):
        minimum = schema.get("minLength")
        if isinstance(minimum, int) and len(value) < minimum:
            raise ContractViolation(f"{path}: string is shorter than minLength")


def iter_header_annotation_nodes(
    node: Any,
    path: tuple[str | int, ...] = (),
) -> list[tuple[tuple[str | int, ...], dict[str, Any]]]:
    """Find x-mcp-header anywhere, including combinators and definitions."""

    found: list[tuple[tuple[str | int, ...], dict[str, Any]]] = []
    if isinstance(node, dict):
        if "x-mcp-header" in node:
            found.append((path, node))
        for key, child in node.items():
            if isinstance(child, (dict, list)):
                found.extend(iter_header_annotation_nodes(child, (*path, key)))
    elif isinstance(node, list):
        for index, child in enumerate(node):
            if isinstance(child, (dict, list)):
                found.extend(iter_header_annotation_nodes(child, (*path, index)))
    return found


def validate_header_annotations(tool: dict[str, Any]) -> list[tuple[tuple[str, ...], str]]:
    """Validate x-mcp-header plus a deployment policy for sensitive fields."""

    input_schema = tool.get("inputSchema")
    if not isinstance(input_schema, dict):
        raise ContractViolation("inputSchema must be an object")
    headers: list[tuple[tuple[str, ...], str]] = []
    seen: set[str] = set()
    for schema_path, property_schema in iter_header_annotation_nodes(input_schema):
        if (
            len(schema_path) != 2
            or schema_path[0] != "properties"
            or not isinstance(schema_path[1], str)
        ):
            raise ContractViolation(
                "x-mcp-header is allowed only on a direct inputSchema property"
            )
        property_name = schema_path[1]
        header_name = property_schema["x-mcp-header"]
        if not isinstance(header_name, str) or not HEADER_TOKEN.fullmatch(header_name):
            raise ContractViolation("x-mcp-header must be a valid HTTP field-name token")
        lowered = header_name.lower()
        if lowered in seen:
            raise ContractViolation("x-mcp-header names must be unique ignoring case")
        seen.add(lowered)
        if property_schema.get("type") not in {"string", "integer", "boolean"}:
            raise ContractViolation("x-mcp-header requires string, integer, or boolean")
        if property_name.lower() in SENSITIVE_NAMES or lowered in SENSITIVE_NAMES:
            raise ContractViolation("sensitive arguments must not be mirrored to headers")
        headers.append(((property_name,), header_name))
    return headers


def validate_tool_descriptor(tool: dict[str, Any]) -> None:
    if not isinstance(tool.get("name"), str) or not tool["name"]:
        raise ContractViolation("tool name must be a non-empty string")
    input_schema = tool.get("inputSchema")
    if not isinstance(input_schema, dict) or input_schema.get("type") != "object":
        raise ContractViolation("inputSchema must be an object schema")
    output_schema = tool.get("outputSchema")
    if output_schema is not None and not isinstance(output_schema, dict):
        raise ContractViolation("outputSchema must be a JSON Schema object")
    if output_schema is not None and iter_header_annotation_nodes(output_schema):
        raise ContractViolation("x-mcp-header is not allowed in outputSchema")
    validate_header_annotations(tool)


def _validate_base64(value: Any, field: str) -> None:
    if not isinstance(value, str):
        raise ContractViolation(f"{field} must be a base64 string")
    try:
        base64.b64decode(value, validate=True)
    except (ValueError, base64.binascii.Error) as exc:
        raise ContractViolation(f"{field} is not valid base64") from exc


def validate_content_block(block: dict[str, Any]) -> None:
    if not isinstance(block, dict):
        raise ContractViolation("content block must be an object")
    block_type = block.get("type")
    if block_type == "text":
        if not isinstance(block.get("text"), str):
            raise ContractViolation("text content requires text")
    elif block_type in {"image", "audio"}:
        _validate_base64(block.get("data"), f"{block_type}.data")
        if not isinstance(block.get("mimeType"), str):
            raise ContractViolation(f"{block_type} content requires mimeType")
    elif block_type == "resource_link":
        if not all(isinstance(block.get(field), str) for field in ("uri", "name")):
            raise ContractViolation("resource_link requires uri and name")
    elif block_type == "resource":
        resource = block.get("resource")
        if not isinstance(resource, dict) or not isinstance(resource.get("uri"), str):
            raise ContractViolation("embedded resource requires a uri")
        if "text" not in resource and "blob" not in resource:
            raise ContractViolation("embedded resource requires text or blob")
    else:
        raise ContractViolation(f"unknown content block type: {block_type}")


def validate_tool_result(tool: dict[str, Any], result: dict[str, Any]) -> None:
    if result.get("resultType") != "complete":
        raise ContractViolation("tool result must be complete")
    content = result.get("content")
    if not isinstance(content, list) or not content:
        raise ContractViolation("tool result must contain at least one content block")
    for block in content:
        validate_content_block(block)

    output_schema = tool.get("outputSchema")
    if output_schema is not None:
        if "structuredContent" not in result:
            raise ContractViolation("outputSchema requires structuredContent")
        validate_json_schema(result["structuredContent"], output_schema)
        if not any(block.get("type") == "text" for block in content):
            raise ContractViolation("structured results require compatibility text")


def _descriptor(
    name: str,
    description: str,
    input_schema: dict[str, Any],
    output_schema: dict[str, Any],
) -> dict[str, Any]:
    return {
        "name": name,
        "description": description,
        "inputSchema": input_schema,
        "outputSchema": output_schema,
    }


TOOLS = [
    _descriptor(
        "tag_catalog",
        "Return an array of tags to prove structuredContent is not object-only.",
        {"type": "object", "additionalProperties": False},
        {"type": "array", "items": {"type": "string"}},
    ),
    _descriptor(
        "evidence_bundle",
        "Return text, media, a resource link, and an embedded resource.",
        {"type": "object", "additionalProperties": False},
        {
            "type": "object",
            "properties": {
                "artifact": {"type": "string"},
                "blockCount": {"type": "integer"},
            },
            "required": ["artifact", "blockCount"],
            "additionalProperties": False,
        },
    ),
    _descriptor(
        "route_report",
        "Route a report by a non-sensitive region argument.",
        {
            "type": "object",
            "properties": {
                "region": {"type": "string", "x-mcp-header": "Region"},
                "report": {"type": "string", "minLength": 1},
            },
            "required": ["region", "report"],
            "additionalProperties": False,
        },
        {
            "type": "object",
            "properties": {
                "region": {"type": "string"},
                "accepted": {"type": "boolean"},
            },
            "required": ["region", "accepted"],
            "additionalProperties": False,
        },
    ),
    _descriptor(
        "blocked_secret_route",
        "Deliberately unsafe descriptor used to exercise client rejection.",
        {
            "type": "object",
            "properties": {
                "token": {"type": "string", "x-mcp-header": "Token"},
            },
            "required": ["token"],
            "additionalProperties": False,
        },
        {"type": "boolean"},
    ),
]


class ContractServer:
    def __init__(self) -> None:
        self.completion_calls: dict[str, int] = {}

    def server_discover(self, params: dict[str, Any]) -> dict[str, Any]:
        validate_request_meta(params)
        return complete(
            supportedVersions=[PROTOCOL_VERSION],
            capabilities={"tools": {"listChanged": False}, "completions": {}},
            ttlMs=300_000,
            cacheScope="public",
        )

    def tools_list(self, params: dict[str, Any]) -> dict[str, Any]:
        validate_request_meta(params)
        ordered = sorted(TOOLS, key=lambda tool: tool["name"])
        has_cursor = "cursor" in params
        cursor = params.get("cursor")
        if not has_cursor:
            page = ordered[:2]
            next_cursor: str | None = ""
        elif cursor == "":
            page = ordered[2:]
            next_cursor = None
        else:
            raise McpError(-32602, "invalid cursor")
        fields: dict[str, Any] = {
            "tools": page,
            "ttlMs": 60_000,
            "cacheScope": "public",
        }
        if next_cursor is not None:
            fields["nextCursor"] = next_cursor
        return complete(**fields)

    def tools_call(self, params: dict[str, Any]) -> dict[str, Any]:
        validate_request_meta(params)
        name = params.get("name")
        tool = next((item for item in TOOLS if item["name"] == name), None)
        if tool is None:
            raise McpError(-32602, "unknown tool")
        arguments = params.get("arguments", {})
        if not isinstance(arguments, dict):
            raise McpError(-32602, "arguments must be an object")
        try:
            validate_json_schema(arguments, tool["inputSchema"])
        except ContractViolation as exc:
            return complete(
                content=[{"type": "text", "text": str(exc)}],
                isError=True,
            )

        if name == "tag_catalog":
            structured: Any = ["contracts", "mcp", "stateless"]
            return complete(
                content=[{"type": "text", "text": json.dumps(structured)}],
                structuredContent=structured,
                isError=False,
            )
        if name == "evidence_bundle":
            structured = {"artifact": "contract-report", "blockCount": 5}
            return complete(
                content=[
                    {"type": "text", "text": json.dumps(structured, sort_keys=True)},
                    {"type": "image", "data": "iVBORw0KGgo=", "mimeType": "image/png"},
                    {"type": "audio", "data": "UklGRg==", "mimeType": "audio/wav"},
                    {
                        "type": "resource_link",
                        "uri": "evidence://contract-report",
                        "name": "contract-report",
                        "mimeType": "application/json",
                    },
                    {
                        "type": "resource",
                        "resource": {
                            "uri": "evidence://contract-report/summary",
                            "mimeType": "text/plain",
                            "text": "All contract checks passed.",
                        },
                    },
                ],
                structuredContent=structured,
                isError=False,
            )
        if name == "route_report":
            if arguments["report"] == "unavailable":
                return complete(
                    content=[{"type": "text", "text": "Report source is unavailable."}],
                    structuredContent={
                        "region": arguments["region"],
                        "accepted": False,
                    },
                    isError=True,
                )
            structured = {"region": arguments["region"], "accepted": True}
            return complete(
                content=[{"type": "text", "text": json.dumps(structured, sort_keys=True)}],
                structuredContent=structured,
                isError=False,
            )
        structured = True
        return complete(
            content=[{"type": "text", "text": "true"}],
            structuredContent=structured,
            isError=False,
        )

    def completion_complete(
        self,
        params: dict[str, Any],
        *,
        principal: str,
    ) -> dict[str, Any]:
        validate_request_meta(params)
        self.completion_calls[principal] = self.completion_calls.get(principal, 0) + 1
        if self.completion_calls[principal] > 3:
            raise McpError(-32029, "completion rate limit exceeded")

        reference = params.get("ref")
        argument = params.get("argument")
        if reference != {"type": "ref/prompt", "name": "deployment_review"}:
            raise McpError(-32602, "unknown completion reference")
        if not isinstance(argument, dict) or argument.get("name") != "environment":
            raise McpError(-32602, "unknown completion argument")
        prefix = argument.get("value")
        if not isinstance(prefix, str):
            raise McpError(-32602, "completion value must be a string")

        allowed = {
            "analyst": ["development", "staging"],
            "operator": ["development", "production", "staging"],
        }.get(principal, [])
        matches = [item for item in allowed if item.startswith(prefix)]
        return complete(
            completion={"values": matches[:100], "total": len(matches), "hasMore": False}
        )

    def dispatch(
        self,
        request: dict[str, Any],
        *,
        principal: str = "analyst",
    ) -> dict[str, Any] | None:
        is_notification = "id" not in request
        request_id = request.get("id")
        try:
            params = request.get("params", {})
            if not isinstance(params, dict):
                raise McpError(-32602, "params must be an object")
            method = request.get("method")
            if method == "server/discover":
                result = self.server_discover(params)
            elif method == "tools/list":
                result = self.tools_list(params)
            elif method == "tools/call":
                result = self.tools_call(params)
            elif method == "completion/complete":
                result = self.completion_complete(params, principal=principal)
            else:
                raise McpError(-32601, "method not found")
            if is_notification:
                return None
            return {"jsonrpc": "2.0", "id": request_id, "result": result}
        except McpError as exc:
            if is_notification:
                return None
            error: dict[str, Any] = {"code": exc.code, "message": exc.message}
            if exc.data is not None:
                error["data"] = exc.data
            return {"jsonrpc": "2.0", "id": request_id, "error": error}


def make_request(request_id: int, method: str, params: dict[str, Any]) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "method": method,
        "params": {**params, "_meta": request_meta()},
    }


MISSING = object()


def _read_path(arguments: dict[str, Any], path: tuple[str, ...]) -> Any:
    value: Any = arguments
    for segment in path:
        if not isinstance(value, dict) or segment not in value:
            return MISSING
        value = value[segment]
    return value


def _parameter_text(value: Any, expected_type: str) -> str:
    if expected_type == "string" and isinstance(value, str):
        return value
    if expected_type == "boolean" and isinstance(value, bool):
        return "true" if value else "false"
    if expected_type == "integer" and isinstance(value, int) and not isinstance(value, bool):
        if not JS_SAFE_INTEGER_MIN <= value <= JS_SAFE_INTEGER_MAX:
            raise ContractViolation("mirrored integer is outside the JavaScript safe range")
        return str(value)
    raise ContractViolation(f"mirrored value does not match declared {expected_type} type")


def _is_plain_visible_ascii(value: str) -> bool:
    return bool(value) and all(0x21 <= ord(character) <= 0x7E for character in value)


def encode_parameter_header_value(value: str) -> str:
    """Apply MCP's exact sentinel encoding when plain transport is ambiguous."""

    sentinel_looking = value.startswith(BASE64_SENTINEL_PREFIX)
    if _is_plain_visible_ascii(value) and not sentinel_looking:
        return value
    payload = base64.b64encode(value.encode("utf-8")).decode("ascii")
    return f"{BASE64_SENTINEL_PREFIX}{payload}{BASE64_SENTINEL_SUFFIX}"


def decode_parameter_header_value(value: str) -> str:
    """Decode a canonical MCP parameter-header value at the HTTP boundary."""

    if not isinstance(value, str):
        raise ContractViolation("parameter header value must be a string")
    if value.startswith(BASE64_SENTINEL_PREFIX):
        if not value.endswith(BASE64_SENTINEL_SUFFIX):
            raise ContractViolation("parameter header uses a malformed base64 sentinel")
        payload = value[len(BASE64_SENTINEL_PREFIX) : -len(BASE64_SENTINEL_SUFFIX)]
        try:
            raw = base64.b64decode(payload, validate=True)
            decoded = raw.decode("utf-8")
        except (ValueError, UnicodeDecodeError, base64.binascii.Error) as exc:
            raise ContractViolation("parameter header uses invalid base64 UTF-8") from exc
        if base64.b64encode(raw).decode("ascii") != payload:
            raise ContractViolation("parameter header base64 is not canonical")
        return decoded
    if not _is_plain_visible_ascii(value):
        raise ContractViolation("plain parameter header is not visible ASCII")
    return value


def build_parameter_headers(
    tool: dict[str, Any],
    arguments: dict[str, Any],
    audit_log: list[dict[str, Any]],
) -> dict[str, str]:
    headers: dict[str, str] = {}
    encoded_names: list[str] = []
    properties = tool["inputSchema"].get("properties", {})
    for path, name in validate_header_annotations(tool):
        value = _read_path(arguments, path)
        if value is MISSING:
            continue
        property_schema = properties[path[0]]
        rendered = _parameter_text(value, property_schema["type"])
        header_name = f"Mcp-Param-{name}"
        encoded = encode_parameter_header_value(rendered)
        headers[header_name] = encoded
        if encoded != rendered:
            encoded_names.append(header_name)
    audit_log.append(
        {
            "event": "parameter_headers_built",
            "headerNames": sorted(headers),
            "encodedHeaderNames": sorted(encoded_names),
        }
    )
    return headers


def validate_parameter_headers(
    tool: dict[str, Any],
    arguments: dict[str, Any],
    headers: dict[str, str],
    audit_log: list[dict[str, Any]],
) -> None:
    """Compare recognized parameter headers with body arguments exactly."""

    normalized: dict[str, list[tuple[str, str]]] = {}
    for supplied_name, supplied_value in headers.items():
        normalized.setdefault(supplied_name.casefold(), []).append(
            (supplied_name, supplied_value)
        )

    checked_names: list[str] = []
    properties = tool["inputSchema"].get("properties", {})
    for path, suffix in validate_header_annotations(tool):
        expected_name = f"Mcp-Param-{suffix}"
        supplied = normalized.get(expected_name.casefold(), [])
        body_value = _read_path(arguments, path)
        if body_value is MISSING:
            if supplied:
                raise ContractViolation("recognized parameter header has no body argument")
            continue
        if not supplied:
            raise ContractViolation("recognized parameter header is missing")
        if len(supplied) != 1:
            raise ContractViolation("recognized parameter header is duplicated")
        decoded = decode_parameter_header_value(supplied[0][1])
        expected = _parameter_text(body_value, properties[path[0]]["type"])
        if decoded != expected:
            raise ContractViolation("recognized parameter header does not match the body")
        checked_names.append(expected_name)

    audit_log.append(
        {
            "event": "parameter_headers_validated",
            "headerNames": sorted(checked_names),
        }
    )


def streamable_http_tool_call(
    server: ContractServer,
    request: dict[str, Any],
    headers: dict[str, str],
    audit_log: list[dict[str, Any]],
    *,
    principal: str = "analyst",
) -> tuple[int, dict[str, Any] | None]:
    """Model the Streamable HTTP parity gate before JSON-RPC dispatch."""

    if request.get("method") == "tools/call":
        params = request.get("params")
        if isinstance(params, dict):
            arguments = params.get("arguments")
            tool = next((item for item in TOOLS if item["name"] == params.get("name")), None)
            if tool is not None and isinstance(arguments, dict):
                try:
                    validate_parameter_headers(tool, arguments, headers, audit_log)
                except ContractViolation as exc:
                    return 400, {
                        "jsonrpc": "2.0",
                        "id": request.get("id"),
                        "error": {
                            "code": -32020,
                            "message": "parameter headers do not match request body",
                            "data": {"reason": str(exc)},
                        },
                    }
    return 200, server.dispatch(request, principal=principal)


class ContractClient:
    def __init__(
        self,
        server: ContractServer,
        *,
        principal: str = "analyst",
        max_list_pages: int = MAX_TOOL_LIST_PAGES,
    ) -> None:
        if type(max_list_pages) is not int or max_list_pages <= 0:
            raise ContractViolation("tools/list page limit must be a positive integer")
        self.server = server
        self.principal = principal
        self.max_list_pages = max_list_pages
        self.rejections: list[dict[str, str]] = []
        self.cursor_trace: list[str | None] = []
        self.tools: dict[str, dict[str, Any]] = {}

    def discover_tools(self) -> dict[str, dict[str, Any]]:
        cursor: str | None = None
        request_id = 1
        seen_cursors: set[str] = set()
        for _ in range(self.max_list_pages):
            params: dict[str, Any] = {}
            if cursor is not None:
                params["cursor"] = cursor
            self.cursor_trace.append(cursor)
            response = self.server.dispatch(make_request(request_id, "tools/list", params))
            if response is None or "error" in response:
                raise ContractViolation("tools/list failed")
            result = response["result"]
            for tool in result["tools"]:
                try:
                    validate_tool_descriptor(tool)
                except ContractViolation as exc:
                    self.rejections.append({"tool": tool.get("name", "<unknown>"), "reason": str(exc)})
                    continue
                self.tools[tool["name"]] = tool
            next_cursor = result.get("nextCursor")
            if next_cursor is None:
                return self.tools
            if not isinstance(next_cursor, str):
                raise ContractViolation("tools/list nextCursor must be a string or null")
            if next_cursor in seen_cursors:
                raise ContractViolation("tools/list returned a repeated or cyclic nextCursor")
            seen_cursors.add(next_cursor)
            cursor = next_cursor
            request_id += 1
        raise ContractViolation(
            f"tools/list exceeded the page limit of {self.max_list_pages}"
        )

    def call(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        if not self.tools:
            self.discover_tools()
        tool = self.tools.get(name)
        if tool is None:
            raise ContractViolation(f"tool is not admitted: {name}")
        response = self.server.dispatch(
            make_request(20, "tools/call", {"name": name, "arguments": arguments}),
            principal=self.principal,
        )
        if response is None or "error" in response:
            raise ContractViolation("tools/call returned a protocol error")
        validate_tool_result(tool, response["result"])
        return response["result"]

    def complete_environment(self, prefix: str) -> list[str]:
        response = self.server.dispatch(
            make_request(
                30,
                "completion/complete",
                {
                    "ref": {"type": "ref/prompt", "name": "deployment_review"},
                    "argument": {"name": "environment", "value": prefix},
                },
            ),
            principal=self.principal,
        )
        if response is None or "error" in response:
            raise ContractViolation("completion request failed")
        return response["result"]["completion"]["values"]


def main() -> None:
    server = ContractServer()
    client = ContractClient(server)
    tools = client.discover_tools()
    tags = client.call("tag_catalog", {})
    bundle = client.call("evidence_bundle", {})
    audit_log: list[dict[str, Any]] = []
    route_tool = tools["route_report"]
    headers = build_parameter_headers(
        route_tool,
        {"region": "europe-λ", "report": "quarterly"},
        audit_log,
    )
    http_status, _ = streamable_http_tool_call(
        server,
        make_request(
            40,
            "tools/call",
            {
                "name": "route_report",
                "arguments": {"region": "europe-λ", "report": "quarterly"},
            },
        ),
        {name.lower(): value for name, value in headers.items()},
        audit_log,
    )

    print("visible tools:", ", ".join(sorted(tools)))
    print("rejected tools:", ", ".join(item["tool"] for item in client.rejections))
    print("cursor trace:", ["<first>" if item is None else repr(item) for item in client.cursor_trace])
    print("array structuredContent:", tags["structuredContent"])
    print("content block types:", [block["type"] for block in bundle["content"]])
    print("mirrored header names:", sorted(headers))
    print("encoded parameter value:", headers["Mcp-Param-Region"].startswith(BASE64_SENTINEL_PREFIX))
    print("HTTP parity status:", http_status)
    print("audit event:", audit_log[0])
    print("analyst completions:", client.complete_environment(""))


if __name__ == "__main__":
    main()

"""Phase 13 Lesson 29: MCP reliability, cancellation, and flow control.
Lesson: ../docs/en.md
Cancellation: https://modelcontextprotocol.io/specification/2026-07-28/basic/patterns/cancellation
Transport: https://modelcontextprotocol.io/specification/2026-07-28/basic/transports/streamable-http
This deterministic simulator uses only Python's standard library.
"""

from __future__ import annotations

import hashlib
import json
import sqlite3
import tempfile
import threading
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


STDIO = "stdio"
STREAMABLE_HTTP = "streamable_http"
IN_PROGRESS = "in_progress"
COMPLETED = "completed"
CANCELLED = "cancelled"


class ReliabilityError(ValueError):
    """Raised when a reliability invariant is violated."""


@dataclass
class InFlightRequest:
    request_id: int | str
    operation: str
    transport: str
    started_at_ms: int
    idle_timeout_ms: int
    max_timeout_ms: int
    progress_token: int | str | None = None
    last_activity_ms: int = 0
    last_progress: float | None = None
    state: str = IN_PROGRESS
    cancel_reason: str | None = None
    response: dict[str, Any] | None = None

    def __post_init__(self) -> None:
        self.last_activity_ms = self.started_at_ms


class RequestCoordinator:
    """Model request cancellation and completion races without wall-clock sleeps."""

    def __init__(self) -> None:
        self.requests: dict[int | str, InFlightRequest] = {}
        self.events: list[dict[str, Any]] = []

    def start(
        self,
        request_id: int | str,
        operation: str,
        *,
        transport: str,
        started_at_ms: int,
        idle_timeout_ms: int,
        max_timeout_ms: int,
        progress_token: int | str | None = None,
    ) -> InFlightRequest:
        if type(request_id) not in (int, str):
            raise ReliabilityError("request id must be an integer or string")
        if progress_token is not None and type(progress_token) not in (int, str):
            raise ReliabilityError("progress token must be an integer or string")
        if request_id in self.requests:
            raise ReliabilityError("request ids must be unique while tracked")
        if transport not in {STDIO, STREAMABLE_HTTP}:
            raise ReliabilityError("unsupported transport")
        if idle_timeout_ms <= 0 or max_timeout_ms < idle_timeout_ms:
            raise ReliabilityError("timeouts must be positive and maximum must cover idle")
        request = InFlightRequest(
            request_id=request_id,
            operation=operation,
            transport=transport,
            started_at_ms=started_at_ms,
            idle_timeout_ms=idle_timeout_ms,
            max_timeout_ms=max_timeout_ms,
            progress_token=progress_token,
        )
        self.requests[request_id] = request
        return request

    def progress(
        self,
        request_id: int | str,
        value: float,
        *,
        now_ms: int,
        total: float | None = None,
        message: str | None = None,
    ) -> dict[str, Any] | None:
        request = self.requests[request_id]
        if request.state != IN_PROGRESS or request.progress_token is None:
            return None
        if request.last_progress is not None and value <= request.last_progress:
            raise ReliabilityError("progress must increase")
        request.last_progress = value
        request.last_activity_ms = now_ms
        params: dict[str, Any] = {
            "progressToken": request.progress_token,
            "progress": value,
        }
        if total is not None:
            params["total"] = total
        if message is not None:
            params["message"] = message
        notification = {
            "jsonrpc": "2.0",
            "method": "notifications/progress",
            "params": params,
        }
        self.events.append(notification)
        return notification

    def timeout_signal(
        self,
        request_id: int | str,
        *,
        now_ms: int,
    ) -> dict[str, Any] | None:
        request = self.requests[request_id]
        if request.state != IN_PROGRESS:
            return None
        hard_due = now_ms - request.started_at_ms >= request.max_timeout_ms
        idle_due = now_ms - request.last_activity_ms >= request.idle_timeout_ms
        if not hard_due and not idle_due:
            return None
        reason = "maximum timeout" if hard_due else "idle timeout"
        return self.client_cancel_signal(request_id, reason=reason)

    def client_cancel_signal(
        self,
        request_id: int | str,
        *,
        reason: str,
    ) -> dict[str, Any]:
        request = self.requests[request_id]
        if request.transport == STDIO:
            return {
                "jsonrpc": "2.0",
                "method": "notifications/cancelled",
                "params": {"requestId": request_id, "reason": reason},
            }
        return {
            "action": "close_response_stream",
            "requestId": request_id,
            "reason": reason,
        }

    def receive_stdio_cancellation(self, notification: dict[str, Any]) -> None:
        """Process the fire-and-forget notification and never return JSON-RPC."""

        if notification.get("method") != "notifications/cancelled":
            return None
        params = notification.get("params")
        if not isinstance(params, dict):
            return None
        request_id = params.get("requestId")
        if type(request_id) not in (int, str):
            return None
        request = self.requests.get(request_id)
        if request is None or request.transport != STDIO or request.state != IN_PROGRESS:
            return None
        request.state = CANCELLED
        reason = params.get("reason")
        request.cancel_reason = reason if isinstance(reason, str) else None
        self.events.append(
            {
                "event": "request_cancelled",
                "requestId": request.request_id,
                "transport": STDIO,
            }
        )
        return None

    def close_http_stream(self, request_id: int | str, *, reason: str) -> None:
        request = self.requests.get(request_id)
        if request is None or request.transport != STREAMABLE_HTTP:
            return None
        if request.state == IN_PROGRESS:
            request.state = CANCELLED
            request.cancel_reason = reason
            self.events.append(
                {
                    "event": "request_cancelled",
                    "requestId": request_id,
                    "transport": STREAMABLE_HTTP,
                }
            )
        return None

    def complete(
        self,
        request_id: int | str,
        result: dict[str, Any],
    ) -> dict[str, Any] | None:
        request = self.requests[request_id]
        if request.state == CANCELLED:
            return None
        if request.state == COMPLETED:
            return request.response
        response = {"jsonrpc": "2.0", "id": request_id, "result": result}
        request.state = COMPLETED
        request.response = response
        self.events.append(response)
        return response

    def server_cancel_subscription(self, request_id: int | str) -> dict[str, Any]:
        request = self.requests.get(request_id)
        if (
            request is None
            or request.transport != STDIO
            or request.operation != "subscriptions/listen"
        ):
            raise ReliabilityError(
                "server-sent notifications/cancelled is reserved for stdio subscriptions/listen"
            )
        if request.state != IN_PROGRESS:
            raise ReliabilityError("subscription request is no longer in progress")
        request.state = CANCELLED
        return {
            "jsonrpc": "2.0",
            "method": "notifications/cancelled",
            "params": {
                "requestId": request_id,
                "reason": "subscription closed by server",
            },
        }


@dataclass(frozen=True)
class RetryDecision:
    classification: str
    reason: str


def classify_retry(
    *,
    side_effect: bool,
    idempotency_key: str | None,
) -> RetryDecision:
    if not side_effect:
        return RetryDecision("safe", "operation is read-only by application contract")
    if idempotency_key:
        return RetryDecision(
            "conditional",
            "retry only with the same idempotency key and identical arguments",
        )
    return RetryDecision(
        "unsafe",
        "a new JSON-RPC id cannot deduplicate a side effect",
    )


class MutationLedger:
    """Commit a simulated mutation and its idempotency record atomically."""

    def __init__(self, database_path: str | Path) -> None:
        self.database_path = str(database_path)
        self._lock = threading.RLock()
        self._connection = sqlite3.connect(
            self.database_path,
            isolation_level=None,
            check_same_thread=False,
            timeout=5.0,
        )
        self._connection.execute("PRAGMA busy_timeout = 5000")
        self._connection.execute("PRAGMA journal_mode = WAL")
        self._connection.execute(
            """
            CREATE TABLE IF NOT EXISTS mutation_counter (
                singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
                executions INTEGER NOT NULL
            )
            """
        )
        self._connection.execute(
            "INSERT OR IGNORE INTO mutation_counter(singleton, executions) VALUES (1, 0)"
        )
        self._connection.execute(
            """
            CREATE TABLE IF NOT EXISTS idempotency_records (
                idempotency_key TEXT PRIMARY KEY,
                fingerprint TEXT NOT NULL,
                result_json TEXT NOT NULL
            )
            """
        )

    def __enter__(self) -> MutationLedger:
        return self

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> None:
        self.close()

    def close(self) -> None:
        with self._lock:
            self._connection.close()

    @property
    def executions(self) -> int:
        with self._lock:
            row = self._connection.execute(
                "SELECT executions FROM mutation_counter WHERE singleton = 1"
            ).fetchone()
        if row is None:
            raise ReliabilityError("mutation counter is missing")
        return int(row[0])

    @staticmethod
    def _fingerprint(account: str, cents: int) -> str:
        payload = json.dumps(
            {"account": account, "cents": cents},
            sort_keys=True,
            separators=(",", ":"),
        )
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()

    def charge(
        self,
        account: str,
        cents: int,
        *,
        rpc_id: int | str,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        if cents <= 0:
            raise ReliabilityError("charge must be positive")
        fingerprint = self._fingerprint(account, cents)
        with self._lock:
            self._connection.execute("BEGIN IMMEDIATE")
            try:
                if idempotency_key is not None:
                    stored = self._connection.execute(
                        """
                        SELECT fingerprint, result_json
                        FROM idempotency_records
                        WHERE idempotency_key = ?
                        """,
                        (idempotency_key,),
                    ).fetchone()
                    if stored is not None:
                        stored_fingerprint, stored_json = stored
                        if stored_fingerprint != fingerprint:
                            raise ReliabilityError(
                                "idempotency key was reused with different arguments"
                            )
                        self._connection.execute("COMMIT")
                        return json.loads(stored_json)

                row = self._connection.execute(
                    "SELECT executions FROM mutation_counter WHERE singleton = 1"
                ).fetchone()
                if row is None:
                    raise ReliabilityError("mutation counter is missing")
                execution_number = int(row[0]) + 1
                result = {
                    "receipt": f"charge-{execution_number:03d}",
                    "rpcId": rpc_id,
                    "account": account,
                    "cents": cents,
                }
                result_json = json.dumps(
                    result,
                    sort_keys=True,
                    separators=(",", ":"),
                )
                self._connection.execute(
                    "UPDATE mutation_counter SET executions = ? WHERE singleton = 1",
                    (execution_number,),
                )
                if idempotency_key is not None:
                    self._connection.execute(
                        """
                        INSERT INTO idempotency_records(
                            idempotency_key, fingerprint, result_json
                        ) VALUES (?, ?, ?)
                        """,
                        (idempotency_key, fingerprint, result_json),
                    )
                self._connection.execute("COMMIT")
                return json.loads(result_json)
            except BaseException:
                if self._connection.in_transaction:
                    self._connection.execute("ROLLBACK")
                raise


@dataclass
class DurableTask:
    task_id: str
    status: str = "working"
    cancel_requested: bool = False


class DurableTaskService:
    """Keep durable task cancellation separate from in-flight request cancellation."""

    def __init__(self) -> None:
        self.tasks: dict[str, DurableTask] = {}

    def create(self, task_id: str) -> DurableTask:
        task = DurableTask(task_id)
        self.tasks[task_id] = task
        return task

    def cancel(self, task_id: str) -> dict[str, Any]:
        task = self.tasks[task_id]
        if task.status == "working":
            task.cancel_requested = True
        return {"resultType": "complete"}

    def worker_checkpoint(self, task_id: str) -> DurableTask:
        task = self.tasks[task_id]
        if task.status == "working" and task.cancel_requested:
            task.status = "cancelled"
        return task

    def finish(self, task_id: str) -> DurableTask:
        task = self.tasks[task_id]
        if task.status == "working":
            task.status = "completed"
        return task


class BoundedSseBuffer:
    """Bound progress memory while preserving a final response."""

    def __init__(self, capacity: int) -> None:
        if capacity < 2:
            raise ReliabilityError("SSE buffer capacity must be at least two")
        self.capacity = capacity
        self.events: list[dict[str, Any]] = []
        self.dropped_progress = 0
        self.needs_refetch = False

    def _drop_oldest_progress(self) -> bool:
        for index, event in enumerate(self.events):
            if event.get("kind") == "progress":
                del self.events[index]
                self.dropped_progress += 1
                self.needs_refetch = True
                return True
        return False

    def push_progress(self, token: int | str, value: float) -> None:
        if self.events and self.events[-1].get("kind") == "progress":
            if self.events[-1].get("token") == token:
                self.events[-1] = {"kind": "progress", "token": token, "value": value}
                self.dropped_progress += 1
                self.needs_refetch = True
                return
        if len(self.events) >= self.capacity and not self._drop_oldest_progress():
            self.dropped_progress += 1
            self.needs_refetch = True
            return
        self.events.append({"kind": "progress", "token": token, "value": value})

    def push_final(self, response: dict[str, Any]) -> None:
        while len(self.events) >= self.capacity:
            if not self._drop_oldest_progress():
                raise ReliabilityError("buffer cannot discard a final response")
        self.events.append({"kind": "final", "response": response})

    def drain(self) -> list[dict[str, Any]]:
        drained = list(self.events)
        self.events.clear()
        return drained


def sse_response_headers() -> dict[str, str]:
    return {
        "Content-Type": "text/event-stream",
        "Cache-Control": "no-cache",
        "X-Accel-Buffering": "no",
    }


def sse_keepalive() -> str:
    return ":\r\n"


def reconnect_plan(
    previous_subscription_id: int | str,
    affected_resources: list[str],
    *,
    unsafe_mutation_was_in_flight: bool,
) -> dict[str, Any]:
    return {
        "newSubscriptionId": f"{previous_subscription_id}-retry",
        "sendLastEventId": False,
        "refetch": sorted(set(affected_resources)),
        "retryUnsafeMutation": not unsafe_mutation_was_in_flight,
    }


def retry_delay_ms(client_id: str, attempt: int) -> int:
    if attempt < 0:
        raise ReliabilityError("attempt must be non-negative")
    ceiling = min(8_000, 250 * (2**attempt))
    floor = max(1, ceiling // 2)
    digest = hashlib.sha256(f"{client_id}:{attempt}".encode("utf-8")).digest()
    jitter = int.from_bytes(digest[:4], "big") % max(1, ceiling - floor + 1)
    return floor + jitter


def main() -> None:
    coordinator = RequestCoordinator()
    coordinator.start(
        7,
        "tools/call",
        transport=STDIO,
        started_at_ms=0,
        idle_timeout_ms=500,
        max_timeout_ms=2_000,
        progress_token="progress-7",
    )
    coordinator.progress(7, 1, now_ms=100, total=3, message="started")
    signal = coordinator.timeout_signal(7, now_ms=600)
    coordinator.receive_stdio_cancellation(signal)
    cancelled_response = coordinator.complete(7, {"resultType": "complete"})

    coordinator.start(
        8,
        "tools/call",
        transport=STDIO,
        started_at_ms=0,
        idle_timeout_ms=500,
        max_timeout_ms=2_000,
    )
    completed_response = coordinator.complete(8, {"resultType": "complete"})
    late_signal = coordinator.client_cancel_signal(8, reason="late user action")
    coordinator.receive_stdio_cancellation(late_signal)

    with tempfile.TemporaryDirectory() as directory:
        with MutationLedger(Path(directory) / "mutations.sqlite3") as ledger:
            first_charge = ledger.charge(
                "acct-7",
                1200,
                rpc_id=41,
                idempotency_key="checkout-7",
            )
            second_charge = ledger.charge(
                "acct-7",
                1200,
                rpc_id=42,
                idempotency_key="checkout-7",
            )
            mutation_executions = ledger.executions

    buffer = BoundedSseBuffer(3)
    for value in range(6):
        buffer.push_progress("progress-9", value)
    buffer.push_final({"jsonrpc": "2.0", "id": 9, "result": {"resultType": "complete"}})

    tasks = DurableTaskService()
    tasks.create("task-29")
    task_ack = tasks.cancel("task-29")
    before_checkpoint = tasks.tasks["task-29"].status
    after_checkpoint = tasks.worker_checkpoint("task-29").status

    print("cancel before completion returns:", cancelled_response)
    print("complete before cancel keeps response:", completed_response is not None)
    print("idempotent receipts equal:", first_charge["receipt"] == second_charge["receipt"])
    print("mutation executions:", mutation_executions)
    print("buffer size and dropped progress:", len(buffer.events), buffer.dropped_progress)
    print("final response preserved:", any(event["kind"] == "final" for event in buffer.events))
    print("task cancel acknowledgement:", task_ack["resultType"])
    print("task status before and after worker checkpoint:", before_checkpoint, after_checkpoint)


if __name__ == "__main__":
    main()

"""Companion code for docs/en.md: admit, pin, monitor, and roll back MCP servers.
Protocol contract: https://modelcontextprotocol.io/specification/2026-07-28/server/discover
Registry contract: https://github.com/modelcontextprotocol/registry/blob/main/docs/reference/server-json/official-registry-requirements.md
Run `python3 main.py` for the finite demo or `python3 -m unittest discover -s tests`.
"""

from __future__ import annotations

import hashlib
import json
from copy import deepcopy
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any, Callable
from urllib.parse import unquote, urlparse, urlunparse


PROTOCOL_VERSION = "2026-07-28"
PUBLISHER_META_KEY = "io.modelcontextprotocol.registry/publisher-provided"
OFFICIAL_META_KEY = "io.modelcontextprotocol.registry/official"
SERVER_INFO_KEY = "io.modelcontextprotocol/serverInfo"


def canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def digest(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()


def namespace_for_domain(domain: str) -> str:
    labels = [label.lower() for label in domain.strip().strip(".").split(".") if label]
    if len(labels) < 2:
        raise ValueError("a verified namespace domain needs at least two labels")
    return ".".join(reversed(labels))


def namespace_matches(server_name: str, verified_namespace: str) -> bool:
    prefix, separator, slug = server_name.partition("/")
    return separator == "/" and bool(slug) and prefix == verified_namespace


def normalized_tools(tools: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return sorted(tools, key=lambda item: (str(item.get("name", "")), canonical_json(item)))


def registry_status(api_meta: dict[str, Any]) -> str:
    official = api_meta.get(OFFICIAL_META_KEY) if isinstance(api_meta, dict) else None
    return str(official.get("status", "")) if isinstance(official, dict) else ""


def is_sha256_digest(value: Any) -> bool:
    return isinstance(value, str) and len(value) == 64 and all(
        character in "0123456789abcdefABCDEF" for character in value
    )


def normalize_https_remote_url(value: Any) -> str | None:
    if not isinstance(value, str) or not value:
        return None
    decoded = unquote(value)
    if any(
        character.isspace() or ord(character) < 0x20 or ord(character) == 0x7F
        for character in value + decoded
    ):
        return None
    try:
        parsed = urlparse(value)
        hostname = parsed.hostname
        username = parsed.username
        password = parsed.password
        port = parsed.port
    except ValueError:
        return None
    if (
        parsed.scheme != "https"
        or not isinstance(hostname, str)
        or not hostname
        or username is not None
        or password is not None
        or parsed.fragment
    ):
        return None
    normalized_host = hostname.lower()
    if ":" in normalized_host:
        normalized_host = f"[{normalized_host}]"
    else:
        try:
            normalized_host = normalized_host.encode("idna").decode("ascii")
        except UnicodeError:
            return None
    netloc = normalized_host
    if port is not None and port != 443:
        netloc = f"{netloc}:{port}"
    return urlunparse(
        ("https", netloc, parsed.path or "/", parsed.params, parsed.query, "")
    )


def is_valid_https_remote_url(value: Any) -> bool:
    return normalize_https_remote_url(value) is not None


def reported_server_info(live: Any) -> dict[str, Any] | None:
    if not isinstance(live, dict):
        return None
    metadata = live.get("_meta")
    value = metadata.get(SERVER_INFO_KEY) if isinstance(metadata, dict) else None
    return deepcopy(value) if isinstance(value, dict) else None


@dataclass(frozen=True)
class Decision:
    allowed: bool
    reasons: tuple[str, ...]
    pin: dict[str, Any] | None = None


class AdmissionLedger:
    def __init__(self, clock: Callable[[], str] | None = None) -> None:
        self.entries: list[dict[str, Any]] = []
        self.clock = clock or (
            lambda: datetime.now(timezone.utc).replace(microsecond=0).isoformat()
        )

    def append(
        self,
        event: str,
        server_name: str,
        version: str,
        outcome: str,
        reasons: list[str],
        evidence: dict[str, Any],
    ) -> dict[str, Any]:
        body = {
            "sequence": len(self.entries) + 1,
            "time": self.clock(),
            "event": event,
            "server": server_name,
            "version": version,
            "outcome": outcome,
            "reasons": list(reasons),
            "evidence": deepcopy(evidence),
            "previousHash": self.entries[-1]["entryHash"] if self.entries else "GENESIS",
        }
        entry = {**body, "entryHash": digest(body)}
        self.entries.append(entry)
        return entry

    def verify(self) -> bool:
        previous_hash = "GENESIS"
        for expected_sequence, entry in enumerate(self.entries, start=1):
            body = {key: value for key, value in entry.items() if key != "entryHash"}
            if entry.get("sequence") != expected_sequence:
                return False
            if entry.get("previousHash") != previous_hash:
                return False
            if entry.get("entryHash") != digest(body):
                return False
            previous_hash = entry["entryHash"]
        return True


class RegistryAdmissionController:
    def __init__(
        self,
        required_capabilities: tuple[str, ...] = ("tools",),
        clock: Callable[[], str] | None = None,
    ) -> None:
        self.required_capabilities = required_capabilities
        self.ledger = AdmissionLedger(clock)
        self.pins: dict[tuple[str, str], dict[str, Any]] = {}
        self.active: dict[str, str] = {}

    def _record_errors(self, record: Any) -> list[str]:
        if not isinstance(record, dict):
            return ["record must be an object"]
        errors: list[str] = []
        for field in ("name", "version", "description"):
            if not isinstance(record.get(field), str) or not record[field].strip():
                errors.append(f"record.{field} must be a non-empty string")

        packages = record.get("packages")
        remotes = record.get("remotes")
        if not (isinstance(packages, list) and packages) and not (
            isinstance(remotes, list) and remotes
        ):
            errors.append("record must declare at least one package or remote")
        if packages is not None and not isinstance(packages, list):
            errors.append("record.packages must be an array")
        elif isinstance(packages, list):
            for index, package in enumerate(packages):
                if not isinstance(package, dict):
                    errors.append(f"record.packages[{index}] must be an object")
                    continue
                for field in ("registryType", "identifier", "version"):
                    if not isinstance(package.get(field), str) or not package[field].strip():
                        errors.append(
                            f"record.packages[{index}].{field} must be a non-empty string"
                        )
                transport = package.get("transport")
                if not isinstance(transport, dict) or not isinstance(
                    transport.get("type"), str
                ) or not transport["type"].strip():
                    errors.append(
                        f"record.packages[{index}].transport.type must be a non-empty string"
                    )
        if remotes is not None and not isinstance(remotes, list):
            errors.append("record.remotes must be an array")
        elif isinstance(remotes, list):
            for index, remote in enumerate(remotes):
                if not isinstance(remote, dict):
                    errors.append(f"record.remotes[{index}] must be an object")
                    continue
                if remote.get("type") not in {"streamable-http", "sse"}:
                    errors.append(
                        f"record.remotes[{index}].type must be streamable-http or sse"
                    )
                url = remote.get("url")
                if not is_valid_https_remote_url(url):
                    errors.append(f"record.remotes[{index}].url must be an HTTPS URL")

        metadata = record.get("_meta", {})
        if not isinstance(metadata, dict):
            errors.append("record._meta must be an object")
        elif set(metadata) - {PUBLISHER_META_KEY}:
            errors.append("record._meta contains a non-publisher key")
        return errors

    def _source_errors(
        self,
        record: dict[str, Any],
        provenance_evidence: dict[str, Any],
    ) -> tuple[list[str], dict[str, Any] | None]:
        if not isinstance(record, dict) or not isinstance(provenance_evidence, dict):
            return ["provenance evidence must be an object"], None
        kind = provenance_evidence.get("kind", "package")
        if kind == "remote":
            remotes = record.get("remotes", [])
            candidates = [item for item in remotes if isinstance(item, dict)] if isinstance(remotes, list) else []
            evidence_url = normalize_https_remote_url(provenance_evidence.get("url"))
            remote = next(
                (
                    item
                    for item in candidates
                    if evidence_url is not None
                    and normalize_https_remote_url(item.get("url")) == evidence_url
                ),
                None,
            )
            errors: list[str] = []
            if remote is None:
                errors.append("verified remote endpoint is absent from the registry record")
                return errors, None
            if remote.get("type") != provenance_evidence.get("transportType"):
                errors.append("verified remote transport does not match the registry record")
            if provenance_evidence.get("verified") is not True:
                errors.append("remote ownership or provenance is not verified")
            if not is_sha256_digest(provenance_evidence.get("digest")):
                errors.append("remote evidence digest is not a SHA-256 digest")
            source = deepcopy({"kind": "remote", **remote})
            source["url"] = evidence_url
            return errors, source
        if kind != "package":
            return [f"unknown provenance evidence kind: {kind}"], None

        packages = record.get("packages", [])
        candidates = [item for item in packages if isinstance(item, dict)] if isinstance(packages, list) else []
        package = next(
            (
                item
                for item in candidates
                if item.get("identifier") == provenance_evidence.get("identifier")
            ),
            None,
        )
        errors: list[str] = []
        if package is None:
            errors.append("verified package identifier is absent from the registry record")
            return errors, None
        if package.get("registryType") != provenance_evidence.get("registryType"):
            errors.append("verified package registry type does not match the registry record")
        transport = package.get("transport")
        transport_type = transport.get("type") if isinstance(transport, dict) else None
        if transport_type != provenance_evidence.get("transportType"):
            errors.append("verified package transport does not match the registry record")
        if provenance_evidence.get("verified") is not True:
            errors.append("package ownership or provenance is not verified")
        if package.get("version") != provenance_evidence.get("version"):
            errors.append("verified package version does not match the registry record")
        if not is_sha256_digest(provenance_evidence.get("digest")):
            errors.append("package evidence digest is not a SHA-256 digest")
        return errors, deepcopy({"kind": "package", **package})

    def _live_errors(self, live: Any) -> list[str]:
        if not isinstance(live, dict):
            return ["live discovery result must be an object"]
        errors: list[str] = []
        supported_versions = live.get("supportedVersions")
        if not isinstance(supported_versions, list) or any(
            not isinstance(version, str) for version in supported_versions
        ):
            errors.append("live supportedVersions must be an array of strings")
        elif PROTOCOL_VERSION not in supported_versions:
            errors.append(f"live server does not advertise {PROTOCOL_VERSION}")
        capabilities = live.get("capabilities", {})
        if not isinstance(capabilities, dict):
            errors.append("live capabilities must be an object")
        else:
            for capability in self.required_capabilities:
                if capability not in capabilities:
                    errors.append(f"live server is missing capability: {capability}")
        tools = live.get("tools")
        if not isinstance(tools, list):
            errors.append("live tool descriptors are missing")
        else:
            for index, tool in enumerate(tools):
                if not isinstance(tool, dict):
                    errors.append(f"live tools[{index}] must be an object")
                    continue
                if not isinstance(tool.get("name"), str) or not tool["name"].strip():
                    errors.append(f"live tools[{index}] needs a non-empty name")
                if not isinstance(tool.get("description"), str) or not tool["description"].strip():
                    errors.append(f"live tools[{index}] needs a non-empty description")
                if not isinstance(tool.get("inputSchema"), dict):
                    errors.append(f"live tools[{index}] needs an inputSchema object")
        return errors

    def admit(
        self,
        record: dict[str, Any],
        api_meta: dict[str, Any],
        verified_namespace: str,
        provenance_evidence: dict[str, Any],
        live: Any,
        registry_source: str = "https://registry.modelcontextprotocol.io",
    ) -> Decision:
        name = str(record.get("name", "<missing>")) if isinstance(record, dict) else "<missing>"
        version = str(record.get("version", "<missing>")) if isinstance(record, dict) else "<missing>"
        reasons = self._record_errors(record)
        status = registry_status(api_meta)
        if status != "active":
            reasons.append(f"registry status is {status or 'missing'}, not active")
        if not namespace_matches(name, verified_namespace):
            reasons.append("server name is outside the verified namespace")
        source_errors, source = self._source_errors(record, provenance_evidence)
        reasons.extend(source_errors)
        reasons.extend(self._live_errors(live))

        evidence = {
            "recordDigest": digest(record),
            "registrySource": registry_source,
            "status": status,
            "verifiedNamespace": verified_namespace,
        }
        if reasons:
            self.ledger.append("admission", name, version, "rejected", reasons, evidence)
            return Decision(False, tuple(reasons))

        assert source is not None
        provenance = {
            "registrySource": registry_source,
            "server": name,
            "registryVersion": version,
            "recordDigest": evidence["recordDigest"],
            "source": source,
            "sourceDigest": provenance_evidence["digest"],
        }
        pin = {
            "server": name,
            "version": version,
            "registryStatus": status,
            "recordDigest": evidence["recordDigest"],
            "source": source,
            "sourceDigest": provenance_evidence["digest"],
            "toolsetDigest": digest(normalized_tools(live["tools"])),
            "provenanceDigest": digest(provenance),
            "reportedServerInfo": reported_server_info(live),
            "quarantined": False,
        }
        self.pins[(name, version)] = deepcopy(pin)
        self.active[name] = version
        self.ledger.append("admission", name, version, "approved", [], pin)
        return Decision(True, (), deepcopy(pin))

    def check_live(self, server_name: str, version: str, live: Any) -> Decision:
        pin = self.pins.get((server_name, version))
        if pin is None:
            return Decision(False, ("version has no admission pin",))
        reasons = self._live_errors(live)
        tools = live.get("tools") if isinstance(live, dict) else None
        tools_valid = isinstance(tools, list) and all(isinstance(tool, dict) for tool in tools)
        observed_toolset = digest(normalized_tools(tools)) if tools_valid else None
        if tools_valid and observed_toolset != pin["toolsetDigest"]:
            reasons.append("live tool descriptors differ from the admitted pin")
        if pin["quarantined"]:
            reasons.append("version is quarantined")
        if reasons:
            pin["quarantined"] = True
            if self.active.get(server_name) == version:
                self.active.pop(server_name)
        outcome = "healthy" if not reasons else "drifted"
        self.ledger.append(
            "live-check",
            server_name,
            version,
            outcome,
            reasons,
            {"pin": pin["provenanceDigest"], "observedToolset": observed_toolset},
        )
        return Decision(not reasons, tuple(reasons), deepcopy(pin))

    def observe_registry_status(self, server_name: str, version: str, status: str) -> None:
        pin = self.pins.get((server_name, version))
        reasons: list[str] = []
        outcome = "observed"
        if pin is None:
            reasons.append("status refers to an unadmitted version")
            outcome = "ignored"
        else:
            pin["registryStatus"] = status
            if status != "active":
                pin["quarantined"] = True
                outcome = "quarantined"
                reasons.append(f"registry status changed to {status}")
                if self.active.get(server_name) == version:
                    self.active.pop(server_name)
        self.ledger.append(
            "registry-status", server_name, version, outcome, reasons, {"status": status}
        )

    def rollback(self, server_name: str, target_version: str, reason: str) -> Decision:
        pin = self.pins.get((server_name, target_version))
        reasons: list[str] = []
        if pin is None:
            reasons.append("rollback target has no admission pin")
        elif pin["quarantined"] or pin["registryStatus"] != "active":
            reasons.append("rollback target is not eligible or is quarantined")
        if reasons:
            self.ledger.append(
                "rollback", server_name, target_version, "rejected", reasons, {"reason": reason}
            )
            return Decision(False, tuple(reasons))
        previous = self.active.get(server_name)
        self.active[server_name] = target_version
        evidence = {"from": previous, "to": target_version, "reason": reason}
        self.ledger.append("rollback", server_name, target_version, "activated", [], evidence)
        return Decision(True, (), deepcopy(pin))


def sample_record(version: str) -> dict[str, Any]:
    return {
        "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
        "name": "com.example/inventory",
        "version": version,
        "description": "Read-only inventory lookup tools",
        "packages": [
            {
                "registryType": "pypi",
                "identifier": "example-mcp-inventory",
                "version": version,
                "transport": {"type": "stdio"},
            }
        ],
        "_meta": {PUBLISHER_META_KEY: {"tier": "internal-approved"}},
    }


def sample_live(version: str, extra_tool: bool = False) -> dict[str, Any]:
    tools = [
        {
            "name": "inventory_get",
            "description": "Fetch one inventory item",
            "inputSchema": {
                "type": "object",
                "properties": {"sku": {"type": "string"}},
                "required": ["sku"],
            },
        }
    ]
    if extra_tool:
        tools.append(
            {
                "name": "inventory_delete",
                "description": "Delete one inventory item",
                "inputSchema": {"type": "object"},
            }
        )
    return {
        "resultType": "complete",
        "supportedVersions": [PROTOCOL_VERSION],
        "capabilities": {"tools": {"listChanged": False}},
        "tools": tools,
        "_meta": {
            SERVER_INFO_KEY: {"name": "com.example/inventory", "version": version}
        },
    }


def evidence_for(version: str) -> dict[str, Any]:
    return {
        "kind": "package",
        "registryType": "pypi",
        "identifier": "example-mcp-inventory",
        "version": version,
        "transportType": "stdio",
        "digest": digest({"wheel": f"example-mcp-inventory-{version}.whl"}),
        "verified": True,
    }


def demo() -> None:
    ticks = iter(f"2026-08-21T10:00:0{second}+00:00" for second in range(9))
    controller = RegistryAdmissionController(clock=lambda: next(ticks))
    active_meta = {OFFICIAL_META_KEY: {"status": "active"}}

    first = controller.admit(
        sample_record("1.0.0"),
        active_meta,
        namespace_for_domain("example.com"),
        evidence_for("1.0.0"),
        sample_live("1.0.0"),
    )
    second = controller.admit(
        sample_record("1.1.0"),
        active_meta,
        namespace_for_domain("example.com"),
        evidence_for("1.1.0"),
        sample_live("1.1.0"),
    )
    drift = controller.check_live("com.example/inventory", "1.1.0", sample_live("1.1.0", True))
    controller.observe_registry_status("com.example/inventory", "1.1.0", "deprecated")
    rollback = controller.rollback("com.example/inventory", "1.0.0", "unexpected delete tool")

    report = {
        "admitted": [first.allowed, second.allowed],
        "driftAllowed": drift.allowed,
        "driftReasons": drift.reasons,
        "rollbackAllowed": rollback.allowed,
        "activeVersion": controller.active["com.example/inventory"],
        "ledgerEntries": len(controller.ledger.entries),
        "ledgerValid": controller.ledger.verify(),
    }
    print(json.dumps(report, indent=2))


